UPDATE composer_highlights SET reason = '모든 조를 다 쓴 첫 곡집이라 쇼팽·쇼스타코비치가 이 틀을 따랐어요. 첫 전주곡은 같은 음형에 화음만 바뀌어요', reason_en = 'The first collection in every key, a model later followed by Chopin and Shostakovich. The first prelude keeps one figure while only the harmony moves' WHERE composer_id = 4 AND piece_id = 10 AND source = 'auto';
UPDATE composer_highlights SET reason = '첼로 한 대로 화음까지 내는 길을 연 곡이라 첼리스트의 기본 레퍼토리예요. 1번 전주곡은 펼친화음 속에 선율이 숨어 있어요', reason_en = 'It showed a single cello could carry harmony, and every cellist plays it. In the first prelude a melody hides inside the broken chords' WHERE composer_id = 4 AND piece_id = 12 AND source = 'auto';
UPDATE composer_highlights SET reason = '악기마다 다른 독주 무리를 세운 여섯 곡으로, 바로크 합주 협주곡의 본보기예요. 3번은 현악기가 셋씩 무리 지어 주고받아요', reason_en = 'Six concertos, each with a different solo group, the model Baroque concerto grosso. No. 3 pits strings in groups of three' WHERE composer_id = 4 AND piece_id = 14 AND source = 'auto';
UPDATE composer_highlights SET reason = '서양 종교 음악의 정점으로 꼽히는 수난곡의 중심 아리아예요. 베드로의 통곡을 알토와 독주 바이올린이 함께 노래해요', reason_en = 'The central aria of a Passion often called the summit of sacred music. Alto and solo violin share Peter''s weeping' WHERE composer_id = 4 AND piece_id = 15 AND source = 'auto';
UPDATE composer_highlights SET reason = '오르간 음악 하면 떠오르는 곡이에요. 짧은 꾸밈음과 내리닫는 음형 뒤 즉흥풍 토카타와 촘촘한 푸가가 이어져요', reason_en = 'The piece that means ''organ music'' to most people. A flourish and plunging run lead into a free toccata and a dense fugue' WHERE composer_id = 4 AND piece_id = 16 AND source = 'auto';
UPDATE composer_highlights SET reason = '변주곡이라는 형식의 정점으로 꼽혀요. 아리아로 시작해 변주 30개를 지나 같은 아리아로 돌아와요', reason_en = 'Seen as the summit of the variation form. An aria, thirty variations, then the same aria again' WHERE composer_id = 4 AND piece_id = 461 AND source = 'auto';
UPDATE composer_highlights SET reason = '비발디 협주곡 형식을 바흐식으로 소화한 협주곡이에요. 2악장에서 낮은 현이 되풀이하는 음형 위로 바이올린이 노래해요', reason_en = 'Vivaldi''s concerto form absorbed into Bach''s style. In the slow movement the violin sings over a repeating bass' WHERE composer_id = 4 AND piece_id = 13888 AND source = 'auto';
UPDATE composer_highlights SET reason = '20대 초반 바흐가 장례식에 쓴 ''악투스 트라기쿠스''예요. 리코더 둘과 비올라 다 감바 둘의 서주로 시작해요', reason_en = 'A funeral cantata by the young Bach, known as the ''Actus tragicus''. It opens with two recorders and two gambas' WHERE composer_id = 4 AND piece_id = 14951 AND source = 'auto';
UPDATE composer_highlights SET reason = '바흐 칸타타 가운데 가장 널리 불리는 코랄이에요. 셋잇단으로 흐르는 반주 위로 코랄 선율이 천천히 놓여요', reason_en = 'The most widely sung chorale from Bach''s cantatas. A slow hymn tune floats over a flowing triplet accompaniment' WHERE composer_id = 4 AND piece_id = 32157 AND source = 'auto';
UPDATE composer_highlights SET reason = '왕이 낸 주제로 즉흥 연주를 해 보인 일에서 나온, 바흐 대위법의 집대성이에요. 여섯 성부가 한 주제를 동시에 엮어요', reason_en = 'Born from Bach improvising on a king''s theme, a summation of his counterpoint. Six voices weave the theme at once' WHERE composer_id = 4 AND piece_id = 32249 AND source = 'auto';
UPDATE composer_highlights SET reason = '지금도 공연되는 가장 오래된 오페라로 꼽혀요. 금관 팡파르로 막을 열고, 오르페오가 노래로 지옥 문을 열어요', reason_en = 'Regarded as the oldest opera still regularly staged. A brass fanfare opens it; Orfeo sings his way into the underworld' WHERE composer_id = 5 AND piece_id = 17 AND source = 'auto';
UPDATE composer_highlights SET reason = '옛 다성음악과 새 오페라 양식을 한 곡에 담은 종교 음악이에요. 자신의 <오르페오> 팡파르를 그대로 가져와 시작해요', reason_en = 'Sacred music that combines old polyphony with the new operatic style. It opens with the fanfare from his own Orfeo' WHERE composer_id = 5 AND piece_id = 18 AND source = 'auto';
UPDATE composer_highlights SET reason = '되풀이 베이스 위에 감정을 싣는 바로크 방식의 이른 본보기예요. 네 음 베이스 위로 님프가 탄식하고 남성 셋이 둘러싸요', reason_en = 'An early model of the Baroque lament over a repeating bass. A nymph grieves over four descending notes while three men look on' WHERE composer_id = 5 AND piece_id = 19 AND source = 'auto';
UPDATE composer_highlights SET reason = '실제 역사 인물로 쓴 첫 오페라로 꼽혀요. 네로와 포페아의 이중창 ''Pur ti miro''로 끝나요', reason_en = 'Considered the first opera on real historical figures. It ends with Nero and Poppea''s duet ''Pur ti miro''' WHERE composer_id = 5 AND piece_id = 20 AND source = 'auto';
UPDATE composer_highlights SET reason = '더블린 자선 공연으로 초연돼 지금도 성탄 시즌마다 공연돼요. 2부 끝 ''할렐루야''에서 트럼펫과 팀파니가 함께 터져요', reason_en = 'Premiered at a Dublin charity concert, it is still staged every Christmas. Trumpets and timpani blaze in the Hallelujah' WHERE composer_id = 6 AND piece_id = 21 AND source = 'auto';
UPDATE composer_highlights SET reason = '왕이 뱃놀이에서 세 번이나 다시 연주시켰다는 기록이 있어요. 호른이 앞장서는 모음곡은 강 위에서 멀리 들리게 썼어요', reason_en = 'Records say the king had it played three times on his barge. The horn-led F major suite was written to carry across the river' WHERE composer_id = 6 AND piece_id = 22 AND source = 'auto';
UPDATE composer_highlights SET reason = '야외 축하 음악의 본보기로, 처음엔 관악기와 타악기로만 썼어요. 서곡에서 금관과 팀파니가 크게 주고받아요', reason_en = 'The model of outdoor celebration music, first scored for winds and percussion alone. Brass and timpani trade blows in the overture' WHERE composer_id = 6 AND piece_id = 23 AND source = 'auto';
UPDATE composer_highlights SET reason = '단순한 화음 진행 위 변주로 바로크 춤곡의 무게를 보여 줘요. 느린 3박자 주제가 영화 <배리 린든> 내내 흘러요', reason_en = 'Variations on a simple chord pattern show the weight of a Baroque dance. Its slow triple-time theme runs through Barry Lyndon' WHERE composer_id = 6 AND piece_id = 433 AND source = 'auto';
UPDATE composer_highlights SET reason = '헨델 오페라 가운데 지금 자주 무대에 오르는 작품이에요. 왕위를 빼앗긴 남편을 기다리는 왕비의 아리아가 중심이에요', reason_en = 'One of Handel''s most staged operas today. Its heart is the queen''s arias for her usurped husband' WHERE composer_id = 6 AND piece_id = 26024 AND source = 'auto';
UPDATE composer_highlights SET reason = '헨델이 런던에서 처음 올린 이탈리아 오페라예요. 아리아 ''울게 하소서''의 느린 사라방드 선율이 가장 유명해요', reason_en = 'Handel''s first Italian opera for London. Its best-known moment is the slow sarabande of ''Lascia ch''io pianga''' WHERE composer_id = 6 AND piece_id = 28368 AND source = 'auto';
UPDATE composer_highlights SET reason = '헨델 생전에 가장 자주 다시 공연된 극음악의 하나예요. 거인 폴리페모스의 아리아가 목가풍 분위기를 확 바꿔요', reason_en = 'One of Handel''s most revived stage works in his lifetime. The giant Polyphemus''s aria breaks the pastoral spell' WHERE composer_id = 6 AND piece_id = 28434 AND source = 'auto';
UPDATE composer_highlights SET reason = '헨델이 독일어로 쓴 몇 안 되는 성악곡이에요. 소프라노와 독주 악기가 같은 선율을 주고받아요', reason_en = 'One of Handel''s few German vocal works. Soprano and solo instrument pass the same melody back and forth' WHERE composer_id = 6 AND piece_id = 28555 AND source = 'auto';
UPDATE composer_highlights SET reason = '로마 시절 스물두 살 헨델의 합창 기량을 보여 준 곡이에요. 다섯 성부 합창이 빠른 음형을 쉼 없이 주고받아요', reason_en = 'The 22-year-old Handel''s choral showpiece from Rome. Five choral parts trade fast figures without pause' WHERE composer_id = 6 AND piece_id = 28579 AND source = 'auto';
UPDATE composer_highlights SET reason = '1727년부터 영국 대관식마다 불린 찬가예요. 현악기가 오래 쌓아 올린 뒤 합창이 한꺼번에 ''차독''을 외쳐요', reason_en = 'Sung at every British coronation since 1727. Strings build slowly before the choir bursts in with ''Zadok''' WHERE composer_id = 6 AND piece_id = 28592 AND source = 'auto';
UPDATE composer_highlights SET reason = '협주곡마다 소네트를 붙여 장면을 지시한 곡이에요. 새소리, 여름 폭풍, 얼음판 걷기를 소리로 옮겨요', reason_en = 'Each concerto comes with a sonnet directing the scene. Birdsong, summer storms and walking on ice in sound' WHERE composer_id = 7 AND piece_id = 28 AND source = 'auto';
UPDATE composer_highlights SET reason = '독주와 합주가 번갈아 나오는 협주곡 틀을 유럽에 퍼뜨린 곡집이에요. 10번은 바이올린 넷이 독주를 넘겨받아요', reason_en = 'The collection that spread the solo-tutti concerto across Europe. In No. 10 four violins pass the solo around' WHERE composer_id = 7 AND piece_id = 29 AND source = 'auto';
UPDATE composer_highlights SET reason = '비발디 종교 음악 가운데 가장 많이 불리는 곡이에요. 트럼펫과 합창이 ''글로리아''를 외치며 열어요', reason_en = 'Vivaldi''s most sung sacred work. Trumpet and choir open with a shout of ''Gloria''' WHERE composer_id = 7 AND piece_id = 30 AND source = 'auto';
UPDATE composer_highlights SET reason = '알토 한 명이 연인의 배신을 노래하는 실내 칸타타예요. 피치카토와 활로 켜는 현이 겹쳐 첫 아리아를 받쳐요', reason_en = 'A chamber cantata for a single alto betrayed by a lover. Plucked and bowed strings combine under the first aria' WHERE composer_id = 7 AND piece_id = 26038 AND source = 'auto';
UPDATE composer_highlights SET reason = '서른 곡 넘는 비발디 바순 협주곡 가운데 자주 연주되는 곡이에요. 바순이 낮은 음과 빠른 도약을 오가요', reason_en = 'One of the most played of Vivaldi''s thirty-plus bassoon concertos. The bassoon leaps between low notes and fast runs' WHERE composer_id = 7 AND piece_id = 26040 AND source = 'auto';
UPDATE composer_highlights SET reason = '옛 ''폴리아'' 화음 진행에 붙인 변주곡으로 바로크 변주의 본보기예요. 두 바이올린이 변주마다 기교를 겨뤄요', reason_en = 'Variations on the old Folia chords, a model of Baroque variation. Two violins compete in each variation' WHERE composer_id = 7 AND piece_id = 28738 AND source = 'auto';
UPDATE composer_highlights SET reason = '비발디 바이올린 기교를 보여 주는 협주곡집이에요. ''별난 것''이라는 제목대로 독주부가 과감하게 뛰놀아요', reason_en = 'A showcase for Vivaldi''s violin writing. True to the title ''The Extravagance'', the solo parts leap boldly' WHERE composer_id = 7 AND piece_id = 28740 AND source = 'auto';
UPDATE composer_highlights SET reason = '황제 카를 6세에게 바친 바이올린 협주곡집이에요. 몇 곡은 독주 바이올린 줄을 다르게 조율해 쓰라고 했어요', reason_en = 'Violin concertos dedicated to Emperor Charles VI. Some ask the soloist to retune the strings' WHERE composer_id = 7 AND piece_id = 28745 AND source = 'auto';
UPDATE composer_highlights SET reason = '비발디 오라토리오 가운데 유일하게 온전히 남은 작품이에요. 여학교 단원들이 모든 배역을 맡고 희귀 악기들이 반주해요', reason_en = 'Vivaldi''s only surviving complete oratorio. The Pietà''s women sing every role, accompanied by rare instruments' WHERE composer_id = 7 AND piece_id = 29222 AND source = 'auto';
UPDATE composer_highlights SET reason = '여러 작곡가의 아리아를 엮던 당시 오페라 관습을 보여 주는 작품이에요. 비발디가 자기 아리아와 남의 아리아를 섞었어요', reason_en = 'Shows the period habit of stitching operas from many composers. Vivaldi mixed his arias with others''' WHERE composer_id = 7 AND piece_id = 29266 AND source = 'auto';
UPDATE composer_highlights SET reason = '영국 현충일 추모식에서 해마다 연주되는 아리아예요. 반음씩 내려가는 베이스 위로 ''Remember me''를 불러요', reason_en = 'Played every year at Britain''s Remembrance Sunday. ''Remember me'' over a bass descending by semitones' WHERE composer_id = 8 AND piece_id = 35 AND source = 'auto';
UPDATE composer_highlights SET reason = '악보가 사라졌다가 1901년에야 다시 발견된 곡이에요. <한여름 밤의 꿈> 막마다 노래와 춤 장면이 끼어들어요', reason_en = 'Its score was lost until 1901. Song-and-dance masques interrupt each act of A Midsummer Night''s Dream' WHERE composer_id = 8 AND piece_id = 36 AND source = 'auto';
UPDATE composer_highlights SET reason = '영국 왕실 장례 음악의 본보기가 된 곡이에요. 금관 행진과 느린 합창이 번갈아 나와요', reason_en = 'A model for English royal funeral music. Brass marches alternate with slow choral anthems' WHERE composer_id = 8 AND piece_id = 37 AND source = 'auto';
UPDATE composer_highlights SET reason = '퍼셀의 선율이 20세기까지 살아남은 예예요. 이 론도가 브리튼 <청소년을 위한 관현악 입문>의 주제가 됐어요', reason_en = 'Proof of how Purcell''s tunes lived on. This Rondeau became the theme of Britten''s Young Person''s Guide' WHERE composer_id = 8 AND piece_id = 38 AND source = 'auto';
UPDATE composer_highlights SET reason = '호로비츠가 앙코르로 즐겨 쳐 널리 알려진 소나타예요. 행진곡 리듬이 처음부터 끝까지 이어져요', reason_en = 'Made famous by Horowitz''s encores. A march rhythm runs from start to finish' WHERE composer_id = 9 AND piece_id = 39 AND source = 'auto';
UPDATE composer_highlights SET reason = '스페인 궁정 시절 쓴 밝은 소나타예요. 사냥 나팔을 흉내 낸 음형으로 시작해요', reason_en = 'A bright sonata from his Spanish court years. It opens imitating hunting horns' WHERE composer_id = 9 AND piece_id = 40 AND source = 'auto';
UPDATE composer_highlights SET reason = '빠른 곡이 많은 스카를라티에게 드문 느린 소나타예요. 두 손이 넘나들며 어두운 화음을 쌓아요', reason_en = 'A rare slow sonata from the usually quick Scarlatti. The hands cross to build dark harmonies' WHERE composer_id = 9 AND piece_id = 41 AND source = 'auto';
UPDATE composer_highlights SET reason = '스페인 기타의 빠른 뜯기를 건반으로 옮긴 곡이에요. 같은 음을 빠르게 연타하며 기타 소리를 흉내 내요', reason_en = 'Spanish guitar strumming translated to the keyboard. Rapid repeated notes imitate the guitar' WHERE composer_id = 9 AND piece_id = 42 AND source = 'auto';
UPDATE composer_highlights SET reason = '피아니스트들이 낭만적인 해석을 즐겨 붙이는 소나타예요. 느린 흐름 속에 두 성부가 조용히 얽혀요', reason_en = 'A sonata pianists love to play romantically. Two voices intertwine at a slow pace' WHERE composer_id = 9 AND piece_id = 43 AND source = 'auto';
UPDATE composer_highlights SET reason = '짧은 한 악장에 스카를라티 양식이 다 들어 있는 곡이에요. 단순한 선율이 두 부분을 각각 되풀이해요', reason_en = 'Scarlatti''s style in one short movement. A simple tune repeats each of its two halves' WHERE composer_id = 9 AND piece_id = 44 AND source = 'auto';
UPDATE composer_highlights SET reason = '555곡 소나타 목록의 첫 곡이자 1738년 첫 곡집의 첫 곡이에요. 짧은 두 부분 형식에 빠른 음형이 이어져요', reason_en = 'First in the 555-sonata catalogue and in his first book of 1738. Quick figures in a short two-part form' WHERE composer_id = 9 AND piece_id = 45 AND source = 'auto';
UPDATE composer_highlights SET reason = '18세기 파리에서 크게 성공한 오페라-발레예요. 4막 ''야만인들의 춤''은 강한 리듬의 론도라 따로 자주 연주돼요', reason_en = 'A big hit in 18th-century Paris. The Act 4 ''Dance of the Savages'', a rhythmic rondo, is often played alone' WHERE composer_id = 10 AND piece_id = 46 AND source = 'auto';
UPDATE composer_highlights SET reason = '1737년 초연 뒤 18세기 내내 다시 무대에 오른 비극 오페라예요. 불멸을 내놓고 형제를 살리는 쌍둥이 이야기예요', reason_en = 'Revived again and again after its 1737 premiere. A twin gives up immortality to save his brother' WHERE composer_id = 10 AND piece_id = 50 AND source = 'auto';
UPDATE composer_highlights SET reason = '쉰 살에 낸 첫 오페라로 대담한 화성이 파리를 둘로 갈랐어요. ''운명의 여신들 3중창''은 가수들이 못 부를 만큼 어려웠어요', reason_en = 'His first opera, at 50, redirected French opera. The Fates'' trio was so daring the singers couldn''t manage it' WHERE composer_id = 10 AND piece_id = 51 AND source = 'auto';
UPDATE composer_highlights SET reason = '왕세자 결혼식 축하 공연으로 쓴 희극 오페라예요. 늪 요정 플라테를 오케스트라가 개구리 울음까지 흉내 내며 놀려요', reason_en = 'A comedy written for a royal wedding. The orchestra mocks the marsh nymph Platée down to frog croaks' WHERE composer_id = 10 AND piece_id = 29364 AND source = 'auto';
UPDATE composer_highlights SET reason = '라모의 마지막 오페라라 그의 관현악이 가장 무르익은 모습이에요. 1763년 리허설 뒤 200년 넘게 공연되지 않았어요', reason_en = 'His last opera, with his most mature orchestration. Rehearsed in 1763, then unperformed for over 200 years' WHERE composer_id = 10 AND piece_id = 29381 AND source = 'auto';
UPDATE composer_highlights SET reason = '후기 바로크의 여러 장르를 한데 모은 곡집이에요. 서곡·협주곡·4중주·소나타가 세 묶음에 고루 들어 있어요', reason_en = 'A compendium of late Baroque genres. Overtures, concertos, quartets and sonatas spread across three sets' WHERE composer_id = 11 AND piece_id = 52 AND source = 'auto';
UPDATE composer_highlights SET reason = '비올라를 독주 악기로 내세운 이른 협주곡이에요. 느림–빠름–느림–빠름 네 악장으로 비올라의 낮은 소리를 살려요', reason_en = 'An early concerto that puts the viola up front. Four movements, slow-fast-slow-fast, showcase its dark tone' WHERE composer_id = 11 AND piece_id = 53 AND source = 'auto';
UPDATE composer_highlights SET reason = '알토 리코더 연주자라면 꼭 거치는 협주 모음곡이에요. 프랑스풍 서곡 뒤 여러 춤곡을 리코더가 이끌어요', reason_en = 'A must for every alto recorder player. A French overture, then dances led by the recorder' WHERE composer_id = 11 AND piece_id = 54 AND source = 'auto';
UPDATE composer_highlights SET reason = '줄거리를 그리는 바로크 표제 음악의 재치 있는 예예요. 풍차와의 싸움, 로시난테와 당나귀의 걸음이 악장마다 나와요', reason_en = 'A witty example of Baroque storytelling music. Movements depict the windmills and the gaits of Rocinante and the donkey' WHERE composer_id = 11 AND piece_id = 55 AND source = 'auto';
UPDATE composer_highlights SET reason = '프랑스와 이탈리아 양식을 섞어 파리에서 크게 성공한 곡이에요. 플루트·바이올린·비올라 다 감바·건반이 선율을 고루 나눠요', reason_en = 'A Paris hit blending French and Italian styles. Flute, violin, gamba and harpsichord share the lines equally' WHERE composer_id = 11 AND piece_id = 56 AND source = 'auto';
UPDATE composer_highlights SET reason = '합주 협주곡 형식을 정리해 헨델·바흐에게 이어 준 곡집이에요. 8번 ''크리스마스 협주곡''은 목가풍 파스토랄레로 끝나요', reason_en = 'The collection that codified the concerto grosso for Handel and Bach. No. 8, the ''Christmas Concerto'', ends with a pastorale' WHERE composer_id = 12 AND piece_id = 59 AND source = 'auto';
UPDATE composer_highlights SET reason = '느림–빠름–느림–빠름 교회 소나타 틀을 다진 곡집이에요. 두 바이올린이 같은 음역에서 선율을 주고받아요', reason_en = 'The collection that set the slow-fast-slow-fast church sonata. Two violins trade lines in the same register' WHERE composer_id = 12 AND piece_id = 60 AND source = 'auto';
UPDATE composer_highlights SET reason = '18세기 바이올린 교육의 기준이 된 소나타집이에요. 마지막 12번은 ''라 폴리아'' 선율의 변주곡이에요', reason_en = 'The 18th century''s standard violin method in sonata form. No. 12 is a set of variations on La Folia' WHERE composer_id = 12 AND piece_id = 29329 AND source = 'auto';
UPDATE composer_highlights SET reason = '고전파 세레나데 가운데 가장 널리 알려진 곡이에요. 현악기가 모두 같은 음형으로 치고 올라가며 시작해요', reason_en = 'The best-known Classical serenade. All the strings rise together in unison at the start' WHERE composer_id = 14 AND piece_id = 66 AND source = 'auto';
UPDATE composer_highlights SET reason = '희극 오페라를 인물 심리극으로 끌어올렸어요. 3막 ''편지 이중창''은 한 사람이 불러 주고 한 사람이 받아 적으며 노래해요', reason_en = 'It raised comic opera to psychological drama. In the Act 3 ''Letter Duet'' one woman dictates as the other writes' WHERE composer_id = 14 AND piece_id = 69 AND source = 'auto';
UPDATE composer_highlights SET reason = '독일어 오페라의 길을 연 작품이에요. 밤의 여왕 아리아는 높은 F음까지 빠르게 오르내려요', reason_en = 'The opera that opened the way for German opera. The Queen of the Night races up to a high F' WHERE composer_id = 14 AND piece_id = 70 AND source = 'auto';
UPDATE composer_highlights SET reason = '정체를 숨긴 의뢰인이 주문했다는 사연으로 유명한 미완성 유작이에요. 모차르트는 ''라크리모사'' 여덟 마디에서 멈췄어요', reason_en = 'Famous for its secret patron and its unfinished state. Mozart stopped after eight bars of the Lacrimosa' WHERE composer_id = 14 AND piece_id = 71 AND source = 'auto';
UPDATE composer_highlights SET reason = '모차르트 피아노 소나타 가운데 가장 유명한 곡이에요. 마지막 악장에서 당시 유행하던 터키 군악대 리듬을 흉내 내요', reason_en = 'Mozart''s most famous piano sonata. The finale imitates the Turkish military bands then in fashion' WHERE composer_id = 14 AND piece_id = 73 AND source = 'auto';
UPDATE composer_highlights SET reason = '클라리넷을 협주곡 독주 악기로 굳힌 곡이에요. 느린 2악장에서 클라리넷이 낮은 음까지 길게 노래해요', reason_en = 'The work that established the clarinet as a concerto soloist. In the slow movement it sings down into its low register' WHERE composer_id = 14 AND piece_id = 74 AND source = 'auto';
UPDATE composer_highlights SET reason = '고전파 변주곡의 교과서 같은 곡이에요. ''반짝반짝 작은 별'' 선율이 열두 번 모습을 바꿔요', reason_en = 'A textbook of Classical variation. ''Twinkle, Twinkle'' changes shape twelve times' WHERE composer_id = 14 AND piece_id = 436 AND source = 'auto';
UPDATE composer_highlights SET reason = '모차르트가 17세에 쓴, 단조 교향곡 두 곡 가운데 첫 곡이에요. 당김음으로 몰아치는 1악장이 극적인 시작을 만들어요', reason_en = 'The first of Mozart''s two minor-key symphonies, written at 17. Its syncopated first movement makes a dramatic start' WHERE composer_id = 14 AND piece_id = 26041 AND source = 'auto';
UPDATE composer_highlights SET reason = '관악 합주곡 가운데 규모가 가장 큰 고전파 작품이에요. 3악장 아다지오에서 관악기들이 긴 선율을 겹겹이 쌓아요', reason_en = 'The largest Classical work for wind ensemble. In the Adagio winds layer long lines one over another' WHERE composer_id = 14 AND piece_id = 26042 AND source = 'auto';
UPDATE composer_highlights SET reason = '1785년 20번을 마친 지 한 달 만에 내놓은 협주곡이에요. 2악장은 약음기 낀 현 위로 피아노가 긴 선율을 불러요', reason_en = 'Finished a month after No. 20 in 1785. In the slow movement the piano sings over muted strings' WHERE composer_id = 14 AND piece_id = 26058 AND source = 'auto';
UPDATE composer_highlights SET reason = '짧은 동기 하나로 교향곡 전체를 짜는 방식을 보여 준 곡이에요. C단조로 시작해 C장조 승리로 끝나요', reason_en = 'It showed how a whole symphony can grow from one short motif. C minor struggle ends in C major triumph' WHERE composer_id = 15 AND piece_id = 75 AND source = 'auto';
UPDATE composer_highlights SET reason = '교향곡에 합창을 넣은 첫 대작이에요. 기악 세 악장 뒤 4악장에서 ''환희의 송가''가 합창으로 터져요', reason_en = 'The first great symphony with chorus. After three orchestral movements the ''Ode to Joy'' bursts out' WHERE composer_id = 15 AND piece_id = 76 AND source = 'auto';
UPDATE composer_highlights SET reason = '젊은 베토벤의 극적인 양식을 보여 준 초기 소나타예요. 느리고 무거운 화음 서주 뒤 빠른 악장이 몰아쳐요', reason_en = 'The early sonata that announced the dramatic young Beethoven. A slow, heavy introduction gives way to a rush' WHERE composer_id = 15 AND piece_id = 79 AND source = 'auto';
UPDATE composer_highlights SET reason = '피아노 협주곡을 교향곡 규모로 키운 베토벤의 마지막 협주곡이에요. 첫 화음 뒤 피아노가 곧바로 카덴차로 뛰어들어요', reason_en = 'Beethoven''s last concerto, on a symphonic scale. After one chord the piano launches into a cadenza' WHERE composer_id = 15 AND piece_id = 80 AND source = 'auto';
UPDATE composer_highlights SET reason = '교향곡만큼 긴 1악장으로 바이올린 협주곡의 규모를 바꾼 곡이에요. 팀파니의 조용한 다섯 번 두드림으로 시작해요', reason_en = 'Its symphony-length first movement changed the violin concerto''s scale. It opens with five soft timpani strokes' WHERE composer_id = 15 AND piece_id = 81 AND source = 'auto';
UPDATE composer_highlights SET reason = '베토벤 피아노 소품 가운데 가장 널리 알려진 곡이에요. 오른손 ''미–레#–미–레#''으로 시작하는 3분 남짓한 곡이에요', reason_en = 'Beethoven''s best-known piano miniature. Three minutes, opening E–D♯–E–D♯' WHERE composer_id = 15 AND piece_id = 82 AND source = 'auto';
UPDATE composer_highlights SET reason = '베토벤이 피아니스트로 무대에 선 마지막 무렵 직접 연주한 3중주예요. 피아노가 넓고 느긋한 주제를 먼저 꺼내고 현이 받아요', reason_en = 'Among the last works Beethoven played in public as a pianist. The piano opens with a broad, unhurried theme' WHERE composer_id = 15 AND piece_id = 441 AND source = 'auto';
UPDATE composer_highlights SET reason = '베토벤이 악보에 ''협주곡처럼'' 쓴다고 적은 소나타예요. 바이올린 혼자 느린 서주를 켠 뒤 피아노와 빠르게 맞붙어요', reason_en = 'Beethoven marked it ''almost like a concerto''. The violin opens alone, then clashes with the piano at speed' WHERE composer_id = 15 AND piece_id = 26029 AND source = 'auto';
UPDATE composer_highlights SET reason = '베토벤이 ''환상곡풍 소나타''라고 이름 붙인 곡이에요. 1악장은 느린 셋잇단 반주가 끝까지 이어져요', reason_en = 'Beethoven titled it ''sonata in the manner of a fantasy''. The slow first movement keeps one triplet accompaniment throughout' WHERE composer_id = 15 AND piece_id = 26698 AND source = 'auto';
UPDATE composer_highlights SET reason = '베토벤이 스스로 최고작이라 부른 미사예요. ''크레도'' 끝에 거대한 푸가가 이어져요', reason_en = 'The mass Beethoven called his greatest work. The Credo ends in a vast fugue' WHERE composer_id = 15 AND piece_id = 26787 AND source = 'auto';
UPDATE composer_highlights SET reason = '런던 청중을 위해 쓴 ''런던 교향곡''의 하나예요. 조용히 되풀이되던 2악장 주제 끝에 오케스트라가 갑자기 크게 쳐요', reason_en = 'One of the ''London'' symphonies. The quiet slow movement is interrupted by a sudden full-orchestra blow' WHERE composer_id = 16 AND piece_id = 83 AND source = 'auto';
UPDATE composer_highlights SET reason = '런던 청중을 위해 쓴 마지막 교향곡 열두 곡 가운데 하나예요. 2악장 반주가 시계처럼 일정하게 똑딱여요', reason_en = 'One of the twelve symphonies Haydn wrote for London. The slow movement ticks steadily like a clock' WHERE composer_id = 16 AND piece_id = 84 AND source = 'auto';
UPDATE composer_highlights SET reason = '교향곡으로 뜻을 전한 재치로 유명한 곡이에요. 끝 악장에서 단원들이 하나둘 퇴장해 바이올린 둘만 남아요', reason_en = 'Famous for delivering a message through music. In the finale players leave one by one until two violins remain' WHERE composer_id = 16 AND piece_id = 85 AND source = 'auto';
UPDATE composer_highlights SET reason = '런던에서 헨델 오라토리오를 듣고 감명받아 쓴 곡이에요. 혼돈을 그린 서주 뒤 ''빛이 있으라''에서 C장조 화음이 터져요', reason_en = 'Written after Haydn heard Handel''s oratorios in London. After the chaos prelude, a C major chord blazes at ''Light''' WHERE composer_id = 16 AND piece_id = 87 AND source = 'auto';
UPDATE composer_highlights SET reason = '새 키 트럼펫의 가능성을 보여 준 첫 대형 협주곡이에요. 낮은 음역에서도 트럼펫이 선율을 불러요', reason_en = 'The first major concerto to show off the new keyed trumpet. It plays melodies even in the low register' WHERE composer_id = 16 AND piece_id = 88 AND source = 'auto';
UPDATE composer_highlights SET reason = '하이든 4중주 가운데 가장 널리 연주되는 곡이에요. 2악장 주제는 지금 독일 국가이고 악기마다 돌아가며 선율을 맡아요', reason_en = 'Haydn''s most widely played quartet. The slow movement''s theme, today''s German anthem, passes to each instrument in turn' WHERE composer_id = 16 AND piece_id = 27166 AND source = 'auto';
UPDATE composer_highlights SET reason = '말씀 하나마다 느린 악장 하나를 붙인 독특한 구성의 곡이에요. 일곱 느린 악장 끝에 빠른 ''지진''으로 끝나요', reason_en = 'A unique design: one slow movement per word of Christ. Seven slow movements end in a fast ''Earthquake''' WHERE composer_id = 16 AND piece_id = 27352 AND source = 'auto';
UPDATE composer_highlights SET reason = '하이든이 영국 국가에 자극받아 쓴 오스트리아 황제 찬가예요. 이 선율이 지금 독일 국가가 됐어요', reason_en = 'An Austrian imperial hymn inspired by ''God Save the King''. Its tune became today''s German anthem' WHERE composer_id = 16 AND piece_id = 27440 AND source = 'auto';
UPDATE composer_highlights SET reason = '플루트 독주곡 레퍼토리로도 자리 잡은 발레 음악이에요. 느린 가운데 부분에서 플루트가 긴 선율을 이끌어요', reason_en = 'Ballet music that became part of the flute repertoire. In the slow middle section the flute leads a long melody' WHERE composer_id = 21 AND piece_id = 62 AND source = 'auto';
UPDATE composer_highlights SET reason = '꾸밈을 줄이고 극을 앞세운 글루크 ''오페라 개혁''의 상징 아리아예요. 아내를 다시 잃은 슬픔을 장조 선율로 불러요', reason_en = 'The emblem of Gluck''s reform, drama over ornament. Orfeo grieves his second loss in a major key' WHERE composer_id = 21 AND piece_id = 63 AND source = 'auto';
UPDATE composer_highlights SET reason = '서문에서 ''음악은 극을 섬겨야 한다''고 밝힌 개혁 선언의 작품이에요. 남편 대신 죽기로 한 왕비가 주인공이에요', reason_en = 'Its preface declared that music should serve the drama. A queen chooses to die for her husband' WHERE composer_id = 21 AND piece_id = 64 AND source = 'auto';
UPDATE composer_highlights SET reason = '글루크 개혁 오페라의 정점으로 꼽혀요. 서곡 없이 폭풍 장면으로 바로 막이 올라요', reason_en = 'Seen as the peak of Gluck''s reform operas. No overture: it opens straight into a storm' WHERE composer_id = 21 AND piece_id = 65 AND source = 'auto';
UPDATE composer_highlights SET reason = 'C.P.E. 바흐 건반 소품 가운데 가장 많이 연주되는 곡이에요. 양손이 번갈아 빠른 음형을 치는 2분 남짓한 곡이에요', reason_en = 'His most played keyboard piece. Two minutes of the hands trading rapid figures' WHERE composer_id = 22 AND piece_id = 103 AND source = 'auto';
UPDATE composer_highlights SET reason = '첼로·플루트·건반 세 가지 판으로 남아 있는 협주곡이에요. 격한 바깥 악장과 노래하는 2악장이 크게 대비돼요', reason_en = 'It survives in versions for cello, flute and keyboard. Fierce outer movements frame a singing slow one' WHERE composer_id = 22 AND piece_id = 104 AND source = 'auto';
UPDATE composer_highlights SET reason = '플루트를 불던 프리드리히 대왕의 궁정에서 쓴 협주곡이에요. 빠른 바깥 악장이 갑자기 강약을 바꾸며 거칠게 몰아쳐요', reason_en = 'Written at the court of the flute-playing Frederick the Great. The outer movements storm with sudden contrasts' WHERE composer_id = 22 AND piece_id = 105 AND source = 'auto';
UPDATE composer_highlights SET reason = '아버지 바흐의 양식과 새 고전파 양식이 만나는 대작이에요. 아버지의 <마니피카트>와 같은 D장조로 썼어요', reason_en = 'Where his father''s style meets the new Classical one. Written in D major, like his father''s Magnificat' WHERE composer_id = 22 AND piece_id = 106 AND source = 'auto';
UPDATE composer_highlights SET reason = '하이든에 앞서 교향곡에 극적인 급변을 들여온 곡이에요. 현악기만으로 갑자기 멈추고 방향을 트는 진행이 이어져요', reason_en = 'It brought dramatic shocks to the symphony before Haydn. Strings alone stop dead and swerve again and again' WHERE composer_id = 22 AND piece_id = 12014 AND source = 'auto';
UPDATE composer_highlights SET reason = '어린 모차르트가 런던에서 J.C. 바흐를 만나 배운 양식의 곡이에요. 독주 바이올린 둘과 첼로가 오케스트라와 주고받아요', reason_en = 'The style the boy Mozart learned from J.C. Bach in London. Two solo violins and cello trade with the orchestra' WHERE composer_id = 23 AND piece_id = 108 AND source = 'auto';
UPDATE composer_highlights SET reason = '어린 모차르트에게 영향을 준 ''런던 바흐''의 교향곡이에요. 2번은 자신의 오페라 <루치오 실라> 서곡이에요', reason_en = 'Symphonies by the ''London Bach'' who shaped the young Mozart. No. 2 is the overture to his opera Lucio Silla' WHERE composer_id = 23 AND piece_id = 29447 AND source = 'auto';
UPDATE composer_highlights SET reason = '클라리넷이 오케스트라에 막 들어오던 때의 이른 협주곡이에요. 만하임 악파답게 빠름–느림–빠름 세 악장이 또렷해요', reason_en = 'An early concerto from when the clarinet was new to the orchestra. Clear fast-slow-fast Mannheim design' WHERE composer_id = 24 AND piece_id = 110 AND source = 'auto';
UPDATE composer_highlights SET reason = '모차르트도 감탄한 만하임 악단을 키운 슈타미츠의 교향곡이에요. 오케스트라가 함께 커지는 ''만하임 크레센도''가 나와요', reason_en = 'By the founder of the Mannheim orchestra Mozart admired. Hear the famous ''Mannheim crescendo''' WHERE composer_id = 24 AND piece_id = 111 AND source = 'auto';
UPDATE composer_highlights SET reason = '바로크 트럼펫의 높은 음역을 그대로 쓴 고전파 초기 협주곡이에요. 클라리노 트럼펫이 아주 높은 음에서 화려하게 움직여요', reason_en = 'An early Classical concerto keeping the Baroque trumpet''s high register. The clarino trumpet dazzles up high' WHERE composer_id = 24 AND piece_id = 112 AND source = 'auto';
UPDATE composer_highlights SET reason = '고전파 소나타 형식을 가장 작은 규모로 보여 주는 교재예요. 여섯 곡 모두 짧은 세 악장 안에 형식이 또렷해요', reason_en = 'Classical sonata form in miniature. Six short three-movement works with crystal-clear structure' WHERE composer_id = 25 AND piece_id = 113 AND source = 'auto';
UPDATE composer_highlights SET reason = '근대 피아노 연습곡의 기초를 놓은 곡집이에요. 100곡에 걸쳐 손가락 기술을 단계별로 다뤄요', reason_en = 'The foundation of the modern piano étude. A hundred pieces build technique step by step' WHERE composer_id = 25 AND piece_id = 114 AND source = 'auto';
UPDATE composer_highlights SET reason = '베토벤에 앞서 피아노 소나타에 극적인 이야기를 담은 곡이에요. 버림받은 디도의 이야기가 세 악장에 이어져요', reason_en = 'A dramatic, story-telling piano sonata ahead of its time. Dido''s abandonment unfolds over three movements' WHERE composer_id = 25 AND piece_id = 115 AND source = 'auto';
UPDATE composer_highlights SET reason = '독일 연가곡의 정점으로 꼽혀요. 실연한 청년이 겨울 길을 걷는 24곡이고, 5번이 ''보리수''예요', reason_en = 'Regarded as the summit of German song cycles. Twenty-four songs of a jilted wanderer; No. 5 is ''The Linden Tree''' WHERE composer_id = 26 AND piece_id = 116 AND source = 'auto';
UPDATE composer_highlights SET reason = '열여덟 살 슈베르트의 첫 출판 가곡이에요. 한 가수가 네 인물을 맡고, 피아노는 말발굽 셋잇단을 쉬지 않고 쳐요', reason_en = 'Schubert''s first published song, written at 18. One singer plays four roles over galloping piano triplets' WHERE composer_id = 26 AND piece_id = 117 AND source = 'auto';
UPDATE composer_highlights SET reason = '피아노 5중주에 콘트라베이스를 넣은 드문 편성이에요. 4악장이 가곡 <송어> 선율의 변주곡이에요', reason_en = 'A rare quintet with double bass. The fourth movement varies his song ''The Trout''' WHERE composer_id = 26 AND piece_id = 118 AND source = 'auto';
UPDATE composer_highlights SET reason = '두 악장만으로 완결된 듯한 낭만주의 교향곡의 출발점이에요. 낮은 현의 어두운 선율로 시작해 첼로가 유명한 노래를 이어받아요', reason_en = 'A starting point of the Romantic symphony, complete-sounding in two movements. Dark low strings open; the cellos sing the famous tune' WHERE composer_id = 26 AND piece_id = 119 AND source = 'auto';
UPDATE composer_highlights SET reason = '슈베르트 실내악 가운데 가장 극적인 4중주로 꼽혀요. 네 악장이 모두 단조이고, 2악장은 가곡 <죽음과 소녀>의 변주예요', reason_en = 'Schubert''s most dramatic quartet. All four movements are in minor keys; the second varies his song ''Death and the Maiden''' WHERE composer_id = 26 AND piece_id = 120 AND source = 'auto';
UPDATE composer_highlights SET reason = '낭만주의 피아노 소품의 본보기가 된 곡집이에요. 3번 G♭장조는 끊기지 않는 긴 선율이 끝까지 이어져요', reason_en = 'A model for the Romantic piano piece. No. 3 in G-flat spins one unbroken melody to the end' WHERE composer_id = 26 AND piece_id = 121 AND source = 'auto';
UPDATE composer_highlights SET reason = '가곡을 넘어 성가처럼 불리게 된 노래예요. 펼친화음 반주가 끝까지 이어지는 위로 엘렌의 기도가 흘러요', reason_en = 'A song that became sung like a hymn. Ellen''s prayer flows over unbroken arpeggios' WHERE composer_id = 26 AND piece_id = 443 AND source = 'auto';
UPDATE composer_highlights SET reason = '연극은 잊혔지만 음악은 남은 슈베르트 부수음악이에요. G장조 발레 음악은 춤곡풍 선율이 단순하게 이어져요', reason_en = 'The play is forgotten, the music survives. The G major ballet music is a simple, dancing tune' WHERE composer_id = 26 AND piece_id = 13086 AND source = 'auto';
UPDATE composer_highlights SET reason = '슈베르트가 생전에 출판한 몇 안 되는 피아노 소품이에요. 스타카토 반주 위에 러시아풍 짧은 선율이 이어져요', reason_en = 'One of the few piano pieces Schubert published in his lifetime. A Russian-style tune over staccato chords' WHERE composer_id = 26 AND piece_id = 13125 AND source = 'auto';
UPDATE composer_highlights SET reason = '1823년에 썼지만 1897년에야 초연된 슈베르트 오페라예요. 기사 이야기를 큰 합창과 관현악으로 그려요', reason_en = 'Written in 1823 but first performed only in 1897. A tale of knights in big choruses and orchestra' WHERE composer_id = 26 AND piece_id = 13466 AND source = 'auto';
UPDATE composer_highlights SET reason = '낭만주의 바이올린 협주곡의 기준이 된 곡이에요. 서주 없이 독주가 바로 주제를 꺼내고 세 악장이 쉬지 않고 이어져요', reason_en = 'The benchmark Romantic violin concerto. The soloist enters at once and the three movements run without a break' WHERE composer_id = 27 AND piece_id = 122 AND source = 'auto';
UPDATE composer_highlights SET reason = '열일곱 살에 쓴 서곡이 낭만주의 서곡의 본보기가 됐어요. 16년 뒤 더한 음악에 ''결혼 행진곡''이 들어 있어요', reason_en = 'The overture he wrote at 17 became a Romantic model. Music added 16 years later includes the Wedding March' WHERE composer_id = 27 AND piece_id = 123 AND source = 'auto';
UPDATE composer_highlights SET reason = '멘델스존 교향곡 가운데 가장 자주 연주되는 곡이에요. 목관의 빠른 반복 화음 위로 바이올린이 치고 나가요', reason_en = 'Mendelssohn''s most performed symphony. Violins take off over fast repeated wind chords' WHERE composer_id = 27 AND piece_id = 124 AND source = 'auto';
UPDATE composer_highlights SET reason = '스무 살 멘델스존이 스코틀랜드 여행에서 얻은 서곡이에요. 첫머리의 짧은 선율이 곡 내내 모양을 바꿔 되돌아와요', reason_en = 'Born on the young Mendelssohn''s Scottish trip. Its short opening phrase keeps returning in new shapes' WHERE composer_id = 27 AND piece_id = 126 AND source = 'auto';
UPDATE composer_highlights SET reason = '슈만이 ''이 시대의 걸작 3중주''라 부른 곡이에요. 첼로가 먼저 꺼내는 1악장 주제가 곡의 중심이에요', reason_en = 'Schumann called it the master trio of the age. The cello''s opening theme is its heart' WHERE composer_id = 27 AND piece_id = 449 AND source = 'auto';
UPDATE composer_highlights SET reason = '스무 살 멘델스존이 웨일스에 머물며 쓴 소품이에요. 2분 남짓 E단조로 빠르게 지나가요', reason_en = 'Written by the 20-year-old Mendelssohn while staying in Wales. Two minutes of fleeting E minor' WHERE composer_id = 27 AND piece_id = 27693 AND source = 'auto';
UPDATE composer_highlights SET reason = '''가사 없는 노래''라는 피아노 장르를 만든 곡집의 첫 곡이에요. 반주 위로 노래 같은 선율이 이어져요', reason_en = 'The first of the set that invented the ''Song without Words''. A singing melody over accompaniment' WHERE composer_id = 27 AND piece_id = 27697 AND source = 'auto';
UPDATE composer_highlights SET reason = '열여섯 살에 쓴 곡으로, 현악 8중주라는 편성을 처음 본격적으로 쓴 작품이에요. 현악기 여덟 대가 교향곡처럼 두텁게 울려요', reason_en = 'Written at 16, the first major work for string octet. Eight strings sound with symphonic weight' WHERE composer_id = 27 AND piece_id = 27698 AND source = 'auto';
UPDATE composer_highlights SET reason = '협주곡 악장을 쉼 없이 잇는 새 방식을 보여 준 곡이에요. 짧은 팡파르가 악장과 악장을 이어 줘요', reason_en = 'It introduced the concerto played without breaks. Short fanfares link the movements' WHERE composer_id = 27 AND piece_id = 27703 AND source = 'auto';
UPDATE composer_highlights SET reason = '1846년 버밍엄 초연에서 여덟 곡을 앙코르할 만큼 성공했어요. 엘리야가 하늘에서 불을 내리는 장면에서 합창이 크게 터져요', reason_en = 'Its 1846 Birmingham premiere was so successful eight numbers were encored. The chorus erupts as Elijah calls down fire' WHERE composer_id = 27 AND piece_id = 27744 AND source = 'auto';
UPDATE composer_highlights SET reason = '쇼팽이 출판을 원하지 않았는데 사후에 나와 오히려 히트한 곡이에요. 빠른 바깥 부분 사이에 느린 노래가 끼어 있어요', reason_en = 'Chopin didn''t want it published; it came out after his death and became a hit. A slow song between fast outer sections' WHERE composer_id = 28 AND piece_id = 128 AND source = 'auto';
UPDATE composer_highlights SET reason = '피아노 ''발라드''라는 장르를 연 첫 곡이에요. 두 주제가 번갈아 커지다 격한 코다로 끝나요', reason_en = 'The piece that created the piano ballade. Two themes grow in turn before a fierce coda' WHERE composer_id = 28 AND piece_id = 129 AND source = 'auto';
UPDATE composer_highlights SET reason = '폴란드 춤곡 폴로네즈를 연주회용 대곡으로 키운 곡이에요. 가운데에서 왼손 옥타브가 쉬지 않고 달려요', reason_en = 'The polonaise grown into a concert epic. In the middle the left hand pounds octaves nonstop' WHERE composer_id = 28 AND piece_id = 130 AND source = 'auto';
UPDATE composer_highlights SET reason = '쇼팽 콩쿠르 결선에서 가장 많이 고르는 협주곡이에요. 긴 오케스트라 서주 뒤 피아노가 노래하듯 들어와요', reason_en = 'The concerto most finalists choose at the Chopin Competition. After a long orchestral introduction the piano enters singing' WHERE composer_id = 28 AND piece_id = 132 AND source = 'auto';
UPDATE composer_highlights SET reason = '젊은 쇼팽의 화려한 연주회 양식을 보여 주는 곡이에요. 잔잔한 피아노 독주 뒤 팡파르와 함께 폴로네즈가 시작돼요', reason_en = 'Young Chopin''s brilliant concert style. A calm solo Andante, then a fanfare and the polonaise' WHERE composer_id = 28 AND piece_id = 26036 AND source = 'auto';
UPDATE composer_highlights SET reason = '쇼팽이 파리에서 연 마지막 연주회에서 친 곡이에요. 왼손이 8분의 12박자로 흔들리고 오른손이 3도로 겹친 선율을 불러요', reason_en = 'Chopin played it at his last Paris concert. The left hand rocks in 12/8 while the right sings in thirds' WHERE composer_id = 28 AND piece_id = 26047 AND source = 'auto';
UPDATE composer_highlights SET reason = '슈만이 ''미친 아이 넷을 한 지붕에 모았다''고 평한 소나타예요. 1분 남짓한 끝 악장은 두 손이 같은 음으로 몰아쳐요', reason_en = 'Schumann said it bound together four of Chopin''s maddest children. The minute-long finale races in bare unison' WHERE composer_id = 28 AND piece_id = 26049 AND source = 'auto';
UPDATE composer_highlights SET reason = '필드가 만든 ''녹턴''을 쇼팽의 장르로 만든 출발점이에요. 같은 선율이 돌아올 때마다 꾸밈음이 늘어나요', reason_en = 'Where Chopin made Field''s nocturne his own. Each return of the melody adds more ornament' WHERE composer_id = 28 AND piece_id = 26068 AND source = 'auto';
UPDATE composer_highlights SET reason = '쇼팽이 ''이보다 아름다운 선율은 못 쓸 것''이라 했다는 연습곡이에요. 느린 E장조 선율이 가운데에서 거세져요', reason_en = 'Chopin reportedly said he had never written a lovelier melody. A slow E major tune turns stormy mid-way' WHERE composer_id = 28 AND piece_id = 26069 AND source = 'auto';
UPDATE composer_highlights SET reason = '쇼팽 왈츠 가운데 가장 널리 알려진 곡이에요. 오른손이 같은 음형을 빠르게 맴도는 2분이 안 되는 곡이에요', reason_en = 'Chopin''s best-known waltz. Under two minutes of the right hand circling a quick figure' WHERE composer_id = 28 AND piece_id = 26114 AND source = 'auto';
UPDATE composer_highlights SET reason = '클라라와 결혼한 1840년 ''가곡의 해''에 쓴 연가곡이에요. 마지막 곡은 노래가 끝난 뒤 피아노 후주가 길게 이어져요', reason_en = 'Written in 1840, his ''year of song'' and the year he married Clara. The piano carries on long after the last song ends' WHERE composer_id = 29 AND piece_id = 134 AND source = 'auto';
UPDATE composer_highlights SET reason = '슈만의 유일한 피아노 협주곡이자 낭만주의 협주곡의 본보기예요. 첫 화음 뒤 피아노가 화음을 내리꽂으며 시작해요', reason_en = 'Schumann''s only piano concerto and a Romantic model. After one chord the piano crashes down in chords' WHERE composer_id = 29 AND piece_id = 136 AND source = 'auto';
UPDATE composer_highlights SET reason = '슈만 교향곡 가운데 가장 밝은 곡으로 꼽혀요. 다섯 악장 가운데 4악장이 쾰른 대성당의 엄숙한 의식을 그려요', reason_en = 'Considered Schumann''s sunniest symphony. Of its five movements, the fourth depicts a ceremony in Cologne Cathedral' WHERE composer_id = 29 AND piece_id = 137 AND source = 'auto';
UPDATE composer_highlights SET reason = '쇼팽·파가니니와 클라라까지 짧은 초상으로 등장하는 모음곡이에요. 네 음 A-S-C-H로 21곡을 짰어요', reason_en = 'Chopin, Paganini and Clara appear in miniature portraits. Twenty-one pieces built on four notes, A-S-C-H' WHERE composer_id = 29 AND piece_id = 138 AND source = 'auto';
UPDATE composer_highlights SET reason = '클라라에게 바친 곡으로 브람스·드보르자크 피아노 5중주의 본보기가 됐어요. 2악장에서 현이 무거운 행진곡을 걸어요', reason_en = 'Dedicated to Clara, it became the model for Brahms''s and Dvořák''s quintets. The strings tread a heavy march in the second movement' WHERE composer_id = 29 AND piece_id = 448 AND source = 'auto';
UPDATE composer_highlights SET reason = '<어린이의 정경> 13곡 가운데 가장 유명한 곡이에요. 3분이 안 되는 느린 곡으로 선율이 한 번 크게 솟았다 내려와요', reason_en = 'The most famous of the 13 Scenes from Childhood. Under three minutes, its melody rises once and falls' WHERE composer_id = 29 AND piece_id = 464 AND source = 'auto';
UPDATE composer_highlights SET reason = '슈만 피아노 소품 가운데 짜임이 독특한 곡으로 꼽혀요. 선율이 가운데 성부에 숨어 두 손 엄지가 나눠 불러요', reason_en = 'Known for its unusual texture. The melody hides in the middle voice, shared by the two thumbs' WHERE composer_id = 29 AND piece_id = 27537 AND source = 'auto';
UPDATE composer_highlights SET reason = '슈만이 남긴 단 하나의 오페라예요. 독일 낭만 오페라를 꿈꾼 슈만의 서곡이 따로 자주 연주돼요', reason_en = 'Schumann''s only opera. Its overture, from his dream of German Romantic opera, is often played alone' WHERE composer_id = 29 AND piece_id = 27587 AND source = 'auto';
UPDATE composer_highlights SET reason = '1850년 뒤셀도르프 시절에 쓴 슈만 말년 가곡이에요. 레나우의 시로 고개 숙인 장미를 노래해요', reason_en = 'A late Schumann song from his Düsseldorf years. A Lenau poem about a drooping rose' WHERE composer_id = 29 AND piece_id = 27596 AND source = 'auto';
UPDATE composer_highlights SET reason = '슈만 생전에는 공개 연주되지 못한 첼로 협주곡이에요. 세 악장이 쉬지 않고 이어지고 독주 첼로가 끝까지 노래해요', reason_en = 'Never performed publicly in Schumann''s lifetime. Three linked movements with the cello singing throughout' WHERE composer_id = 29 AND piece_id = 27635 AND source = 'auto';
UPDATE composer_highlights SET reason = '리스트가 만든 ''교향시''라는 장르를 널리 알린 곡이에요. 짧은 동기 하나가 사랑·폭풍·전원·전투로 모습을 바꿔요', reason_en = 'The piece that made Liszt''s symphonic poem famous. One motif turns into love, storm, pastoral and battle' WHERE composer_id = 30 AND piece_id = 142 AND source = 'auto';
UPDATE composer_highlights SET reason = '평론가 한슬리크가 비꼬아 ''트라이앵글 협주곡''이라 부른 곡이에요. 네 부분을 한 덩어리로 쉬지 않고 이어요', reason_en = 'The critic Hanslick mocked it as the ''Triangle Concerto''. Its four sections run as one' WHERE composer_id = 30 AND piece_id = 450 AND source = 'auto';
UPDATE composer_highlights SET reason = '괴테 <파우스트>를 교향곡으로 옮긴 리스트의 대작이에요. 파우스트·그레트헨·메피스토펠레스를 악장 하나씩에 그려요', reason_en = 'Liszt''s great Faust symphony. One movement each for Faust, Gretchen and Mephistopheles' WHERE composer_id = 30 AND piece_id = 27972 AND source = 'auto';
UPDATE composer_highlights SET reason = '피사의 벽화 ''죽음의 승리''를 보고 구상했다는 곡이에요. 중세 성가 ''진노의 날''을 피아노가 거칠게 두드려요', reason_en = 'Said to be inspired by the fresco ''The Triumph of Death'' in Pisa. The piano hammers out the ''Dies irae''' WHERE composer_id = 30 AND piece_id = 27984 AND source = 'auto';
UPDATE composer_highlights SET reason = '리스트가 20년 넘게 고쳐 다듬은 <초절기교 연습곡>의 넷째 곡이에요. 위고의 시대로 말에 묶여 끌려가는 마제파를 그려요', reason_en = 'From the études Liszt revised over two decades. After Hugo, Mazeppa bound to a galloping horse' WHERE composer_id = 30 AND piece_id = 27990 AND source = 'auto';
UPDATE composer_highlights SET reason = '파가니니 연주에 충격받은 리스트가 그 기교를 피아노로 옮긴 곡이에요. 오른손이 높은 D#음을 계속 짚어 종소리를 내요', reason_en = 'Liszt, stunned by Paganini, carried his tricks to the piano. The right hand keeps striking a high D-sharp like a bell' WHERE composer_id = 30 AND piece_id = 27991 AND source = 'auto';
UPDATE composer_highlights SET reason = '한 악장 안에 소나타 전체를 담은 낭만주의 피아노 소나타의 정점이에요. 첫머리 동기 몇 개로 30분 가까이 짜요', reason_en = 'The peak of the Romantic sonata, a whole sonata in one movement. Nearly 30 minutes from a few opening motifs' WHERE composer_id = 30 AND piece_id = 28066 AND source = 'auto';
UPDATE composer_highlights SET reason = '조성이 흔들리는 리스트 말년 양식을 보여 주는 소품이에요. 3분 남짓한 왈츠가 조용히 사라지며 끝나요', reason_en = 'A glimpse of Liszt''s late, key-blurring style. A three-minute waltz that fades away' WHERE composer_id = 30 AND piece_id = 28106 AND source = 'auto';
UPDATE composer_highlights SET reason = '헝가리 집시 악단의 연주를 리스트가 피아노로 옮긴 곡이에요. 느린 ''라산'' 뒤 빠른 ''프리스카''로 몰아쳐요', reason_en = 'Liszt''s piano version of Hungarian Gypsy band music. A slow lassan, then a whirling friska' WHERE composer_id = 30 AND piece_id = 28130 AND source = 'auto';
UPDATE composer_highlights SET reason = '원래 가곡 ''사랑할 수 있는 한 사랑하라''를 리스트가 피아노로 옮긴 곡이에요. 선율이 짧은 카덴차 두 번을 거쳐 이어져요', reason_en = 'Liszt''s piano version of his song ''Love as long as you can''. The melody passes through two short cadenzas' WHERE composer_id = 30 AND piece_id = 28235 AND source = 'auto';
UPDATE composer_highlights SET reason = '4부작 <니벨룽의 반지>에서 가장 유명한 대목이에요. 발퀴레들이 말 달리는 3막 첫머리를 금관이 크게 이끌어요', reason_en = 'The most famous moment of the Ring cycle. Brass drive the Valkyries'' ride at the start of Act 3' WHERE composer_id = 31 AND piece_id = 144 AND source = 'auto';
UPDATE composer_highlights SET reason = '''트리스탄 화음''으로 조성 음악의 한계를 연 작품이에요. 첫 화음이 네 시간 내내 풀리지 않다가 끝에서야 풀려요', reason_en = 'The ''Tristan chord'' pushed tonality to its limit. Unresolved for four hours, it resolves only in the Liebestod' WHERE composer_id = 31 AND piece_id = 145 AND source = 'auto';
UPDATE composer_highlights SET reason = '결혼식 신부 입장 음악의 원곡이에요. 3막 첫머리에서 합창이 신혼 방으로 두 사람을 이끌며 불러요', reason_en = 'The original ''Here Comes the Bride''. The chorus leads the couple to the bridal chamber in Act 3' WHERE composer_id = 31 AND piece_id = 146 AND source = 'auto';
UPDATE composer_highlights SET reason = '바그너가 자기 양식을 처음 찾은 오페라예요. 폭풍 치는 바다 서곡과 유령선 선장의 주제가 곡 전체를 묶어요', reason_en = 'Where Wagner found his own voice. A storm-at-sea overture and the ghost captain''s theme bind it together' WHERE composer_id = 31 AND piece_id = 26053 AND source = 'auto';
UPDATE composer_highlights SET reason = '바그너에게 첫 큰 성공을 안긴 그랜드 오페라예요. 서곡이 트럼펫 한 음을 길게 부는 신호로 시작해요', reason_en = 'The grand opera that gave Wagner his first big success. The overture opens with a single held trumpet note' WHERE composer_id = 31 AND piece_id = 26054 AND source = 'auto';
UPDATE composer_highlights SET reason = '1861년 파리 공연이 귀족들의 야유로 사흘 만에 막을 내린 오페라예요. 서곡이 ''순례자의 합창'' 선율로 시작해요', reason_en = 'Its 1861 Paris run was shouted down by aristocrats after three nights. The overture opens with the Pilgrims'' Chorus' WHERE composer_id = 31 AND piece_id = 26055 AND source = 'auto';
UPDATE composer_highlights SET reason = '<트리스탄과 이졸데>로 가는 길목의 가곡집이에요. 다섯 곡 가운데 두 곡이 그 오페라의 습작이에요', reason_en = 'Songs on the road to Tristan und Isolde. Two of the five are studies for the opera' WHERE composer_id = 31 AND piece_id = 29925 AND source = 'auto';
UPDATE composer_highlights SET reason = '바그너가 남긴 드문 순수 관현악곡이에요. 아내 생일 아침 집 계단에서 작은 악단이 연주해 깨운 곡이에요', reason_en = 'A rare purely orchestral Wagner work. A small band played it on the stairs to wake his wife on her birthday' WHERE composer_id = 31 AND piece_id = 29933 AND source = 'auto';
UPDATE composer_highlights SET reason = '바그너가 바이로이트 극장만을 위해 쓴 마지막 오페라예요. 성배 기사단의 의식 장면을 느린 합창과 종소리로 그려요', reason_en = 'Wagner''s last opera, written for Bayreuth alone. The Grail ceremony unfolds in slow chorus and bells' WHERE composer_id = 31 AND piece_id = 29939 AND source = 'auto';
UPDATE composer_highlights SET reason = '세계에서 가장 많이 공연되는 오페라로 꼽혀요. 1막 ''축배의 노래''에서 비올레타와 알프레도가 잔을 들고 주고받아요', reason_en = 'Ranked the world''s most performed opera. In the Act 1 drinking song Violetta and Alfredo trade verses, glasses raised' WHERE composer_id = 32 AND piece_id = 148 AND source = 'auto';
UPDATE composer_highlights SET reason = '베르디 중기 3대 오페라의 하나예요. 3막 ''여자의 마음''은 공작이 가볍게 부르는데, 바로 그 뒤 비극이 닥쳐요', reason_en = 'One of Verdi''s three great middle-period operas. The Duke tosses off ''La donna è mobile'' just before tragedy strikes' WHERE composer_id = 32 AND piece_id = 149 AND source = 'auto';
UPDATE composer_highlights SET reason = '카이로 오페라 극장의 의뢰로 쓴 오페라예요. 2막 ''개선 행진곡''에서 긴 ''아이다 트럼펫''이 무대에 나와요', reason_en = 'Commissioned by the Cairo opera house. In the Triumphal March the long ''Aida trumpets'' appear on stage' WHERE composer_id = 32 AND piece_id = 150 AND source = 'auto';
UPDATE composer_highlights SET reason = '베르디를 이탈리아 국민 작곡가로 만든 합창이에요. 대부분을 합창 전체가 한 음으로 같이 불러요', reason_en = 'The chorus that made Verdi Italy''s national composer. Most of it is sung in unison' WHERE composer_id = 32 AND piece_id = 151 AND source = 'auto';
UPDATE composer_highlights SET reason = '오페라 작곡가의 극적 감각을 종교 음악에 쏟은 레퀴엠이에요. 큰북이 엇박으로 내리치는 ''진노의 날''이 몇 번이고 돌아와요', reason_en = 'An opera composer''s drama poured into a requiem. The Dies irae, with off-beat bass-drum blows, keeps returning' WHERE composer_id = 32 AND piece_id = 152 AND source = 'auto';
UPDATE composer_highlights SET reason = '브람스 교향곡 가운데 가장 짧고 내밀한 곡이에요. 3악장 첼로 선율이 영화 <이수>에 쓰여 널리 알려졌어요', reason_en = 'Brahms''s shortest, most intimate symphony. Its third-movement cello tune became famous in Goodbye Again' WHERE composer_id = 33 AND piece_id = 154 AND source = 'auto';
UPDATE composer_highlights SET reason = '베토벤·멘델스존과 함께 3대 바이올린 협주곡으로 꼽혀요. 2악장 선율을 오보에가 먼저 길게 불러요', reason_en = 'One of the three great violin concertos. The oboe sings the slow movement''s melody first' WHERE composer_id = 33 AND piece_id = 156 AND source = 'auto';
UPDATE composer_highlights SET reason = '라틴어 대신 독일어 성경으로 쓴 새 형식의 레퀴엠이에요. ''슬퍼하는 사람은 복이 있나니''로 시작해 남은 이를 위로해요', reason_en = 'A new kind of requiem in German, from the Bible. It begins ''Blessed are they that mourn'', comforting the living' WHERE composer_id = 33 AND piece_id = 157 AND source = 'auto';
UPDATE composer_highlights SET reason = '바로크 형식으로 교향곡을 마무리한 브람스의 마지막 교향곡이에요. 4악장은 여덟 마디 주제 위로 변주 30개가 이어져요', reason_en = 'His last symphony ends with a Baroque form: thirty variations on an eight-bar theme' WHERE composer_id = 33 AND piece_id = 452 AND source = 'auto';
UPDATE composer_highlights SET reason = '세계에서 가장 유명한 자장가의 하나예요. 친구의 둘째 아기를 위해 쓴 단순한 3박자 선율이에요', reason_en = 'One of the world''s most famous lullabies. A simple triple-time tune for a friend''s second baby' WHERE composer_id = 33 AND piece_id = 11345 AND source = 'auto';
UPDATE composer_highlights SET reason = '출판되자마자 크게 팔려 브람스를 대중 작곡가로 만든 곡집이에요. 느렸다 빨라졌다 속도가 확 바뀌는 집시풍 선율이에요', reason_en = 'The bestseller that made Brahms a popular composer. A Gypsy-style tune that lurches between slow and fast' WHERE composer_id = 33 AND piece_id = 11355 AND source = 'auto';
