UPDATE composer_highlights SET reason = '교향곡 같은 협주곡이라는 브람스 양식의 출발점이에요. 팀파니가 길게 울리는 위로 오케스트라가 거칠게 열어요', reason_en = 'Where Brahms''s symphonic concerto began. The orchestra opens fiercely over a long timpani roll' WHERE composer_id = 33 AND piece_id = 32334 AND source = 'auto';
UPDATE composer_highlights SET reason = '젊은 브람스와 노년 브람스가 한 곡에 있는 3중주예요. 스무 살 무렵 쓴 곡을 35년 뒤 크게 고쳤어요', reason_en = 'Young and old Brahms in one trio. Written around 20, heavily revised 35 years later' WHERE composer_id = 33 AND piece_id = 32339 AND source = 'auto';
UPDATE composer_highlights SET reason = '빈에 정착한 브람스가 빈 왈츠를 피아노로 옮긴 곡집이에요. 15번은 1분 남짓한 짧은 왈츠예요', reason_en = 'Brahms''s piano waltzes in Viennese style, written after he settled in Vienna. No. 15 lasts about a minute' WHERE composer_id = 33 AND piece_id = 32348 AND source = 'auto';
UPDATE composer_highlights SET reason = '교향곡을 느린 악장으로 끝낸 파격으로 유명해요. 3악장이 크게 끝난 뒤 4악장이 아주 여리게 사라져요', reason_en = 'Famous for ending a symphony slowly. After the loud third movement, the finale fades to nothing' WHERE composer_id = 34 AND piece_id = 158 AND source = 'auto';
UPDATE composer_highlights SET reason = '처음 들려준 루빈시테인에게 혹평받았다가 보스턴 초연으로 성공한 협주곡이에요. 호른 신호 뒤 첫 주제는 다시 안 나와요', reason_en = 'Panned by Nikolai Rubinstein, it triumphed at its Boston premiere. The famous opening theme never returns' WHERE composer_id = 34 AND piece_id = 159 AND source = 'auto';
UPDATE composer_highlights SET reason = '처음 헌정받은 바이올리니스트가 ''연주 불가''라 했던 곡이에요. 끝 악장은 러시아 춤곡풍으로 빠르게 몰아쳐요', reason_en = 'The violinist it was meant for called it unplayable. The finale races like a Russian dance' WHERE composer_id = 34 AND piece_id = 160 AND source = 'auto';
UPDATE composer_highlights SET reason = '크리스마스 발레의 대명사예요. ''사탕 요정의 춤''에서 첼레스타가, ''꽃의 왈츠''에서 하프가 앞장서요', reason_en = 'THE Christmas ballet. The celesta leads the Sugar Plum Fairy, the harp the Waltz of the Flowers' WHERE composer_id = 34 AND piece_id = 161 AND source = 'auto';
UPDATE composer_highlights SET reason = '초연 땐 실패했다가 차이콥스키 사후 새 안무로 살아난 발레예요. 오보에의 ''정경'' 주제가 백조 오데트의 선율이에요', reason_en = 'A flop at first, revived with new choreography after Tchaikovsky''s death. The oboe''s ''Scene'' theme is Odette''s melody' WHERE composer_id = 34 AND piece_id = 162 AND source = 'auto';
