UPDATE composer_highlights SET reason = '''운명''의 주제가 단조에서 장조로 바뀌어 승리로 끝나는 교향곡이에요. 1악장 클라리넷 주제가 네 악장 내내 돌아와요', reason_en = 'A fate theme turns from minor to major and ends in triumph. The clarinet''s opening theme returns in every movement' WHERE composer_id = 34 AND piece_id = 453 AND source = 'auto';
UPDATE composer_highlights SET reason = '차이콥스키가 ''마음에서 우러나 쓴 곡''이라며 아낀 세레나데예요. 2악장 왈츠가 따로 자주 연주돼요', reason_en = 'Tchaikovsky said he wrote it from inner compulsion. Its waltz is often played alone' WHERE composer_id = 34 AND piece_id = 454 AND source = 'auto';
UPDATE composer_highlights SET reason = '잡지에 달마다 한 곡씩 실은 피아노 소품집이에요. 6월은 느린 G단조 뱃노래예요', reason_en = 'Piano pieces published one a month in a magazine. June is a slow G minor barcarolle' WHERE composer_id = 34 AND piece_id = 26034 AND source = 'auto';
UPDATE composer_highlights SET reason = '차이콥스키 가곡 가운데 널리 알려진 자장가예요. 라흐마니노프가 피아노곡으로 옮겼어요', reason_en = 'A well-known Tchaikovsky song. Rachmaninoff transcribed it for piano' WHERE composer_id = 34 AND piece_id = 28250 AND source = 'auto';
UPDATE composer_highlights SET reason = '바이올린 독주 기교의 교과서가 된 곡집이에요. 24번 주제를 리스트·브람스·라흐마니노프가 다시 가져다 썼어요', reason_en = 'The textbook of solo violin technique. Liszt, Brahms and Rachmaninoff all reused the theme of No. 24' WHERE composer_id = 35 AND piece_id = 164 AND source = 'auto';
UPDATE composer_highlights SET reason = '파가니니가 자기 연주를 위해 쓰고 생전에 악보를 감춰 둔 협주곡이에요. 3악장 ''라 캄파넬라''에서 작은 종이 울려요', reason_en = 'Paganini wrote it for himself and kept the score hidden. A little bell rings in ''La campanella''' WHERE composer_id = 35 AND piece_id = 165 AND source = 'auto';
UPDATE composer_highlights SET reason = '파가니니 협주곡 가운데 가장 자주 연주되는 곡이에요. 독주자는 줄을 반음 높여 D장조로, 오케스트라는 E♭장조로 연주해요', reason_en = 'Paganini''s most performed concerto. The soloist tunes up a semitone to play in D while the orchestra is in E-flat' WHERE composer_id = 35 AND piece_id = 166 AND source = 'auto';
UPDATE composer_highlights SET reason = '초연 날 야유가 쏟아졌지만 곧 로시니 최고 히트작이 된 오페라예요. 피가로가 ''피가로, 피가로'' 하고 외치며 등장해요', reason_en = 'Booed on opening night, it soon became Rossini''s biggest hit. Figaro enters shouting his own name' WHERE composer_id = 36 AND piece_id = 167 AND source = 'auto';
UPDATE composer_highlights SET reason = '로시니 서곡 가운데 가장 유명한 곡이에요. 첼로 독주로 조용히 시작해 폭풍을 지나 빠른 ''스위스 군대의 행진''으로 끝나요', reason_en = 'Rossini''s most famous overture. It opens with solo cellos, passes a storm and ends in the galloping march' WHERE composer_id = 36 AND piece_id = 168 AND source = 'auto';
UPDATE composer_highlights SET reason = '로시니 서곡 양식을 잘 보여 주는 곡이에요. 작은북 연타로 시작해 점점 커지는 ''로시니 크레센도''가 나와요', reason_en = 'A model Rossini overture. Snare-drum rolls open it, and the famous ''Rossini crescendo'' builds' WHERE composer_id = 36 AND piece_id = 169 AND source = 'auto';
UPDATE composer_highlights SET reason = '스물한 살 로시니를 스타로 만든 희극 오페라예요. 1막 끝에서 인물들이 의성어를 쏟아내는 합창이 유명해요', reason_en = 'The comedy that made the 21-year-old Rossini a star. The Act 1 finale dissolves into nonsense sounds' WHERE composer_id = 36 AND piece_id = 29621 AND source = 'auto';
UPDATE composer_highlights SET reason = '로시니가 3주 남짓 만에 썼다는 희극 오페라예요. 요정 대신 철학자가 신데렐라를 돕고, 끝 아리아에서 메조가 기교를 뽐내요', reason_en = 'Rossini reportedly wrote it in about three weeks. A philosopher replaces the fairy godmother; the mezzo''s final aria dazzles' WHERE composer_id = 36 AND piece_id = 29629 AND source = 'auto';
UPDATE composer_highlights SET reason = '이야기를 따라가는 ''표제 교향곡''의 출발점이에요. 연인을 뜻하는 선율이 다섯 악장마다 모습을 바꿔 나와요', reason_en = 'The founding programme symphony. The beloved''s theme reappears, transformed, in all five movements' WHERE composer_id = 37 AND piece_id = 170 AND source = 'auto';
UPDATE composer_highlights SET reason = '베를리오즈를 헝가리 청중에게 각인시킨 행진곡이에요. ''라코치 행진곡'' 선율을 관현악으로 크게 키웠어요', reason_en = 'The march that won over Hungarian audiences. The Rákóczi tune blown up for full orchestra' WHERE composer_id = 37 AND piece_id = 171 AND source = 'auto';
UPDATE composer_highlights SET reason = '실패한 자기 오페라 <벤베누토 첼리니>의 선율을 살려 쓴 서곡이에요. 잉글리시 호른 독주 뒤 빠른 살타렐로로 넘어가요', reason_en = 'Berlioz rescued tunes from his failed opera Benvenuto Cellini. An English horn solo, then a racing saltarello' WHERE composer_id = 37 AND piece_id = 172 AND source = 'auto';
UPDATE composer_highlights SET reason = '프랑스 그랜드 오페라의 최대작으로 꼽혀요. 트로이 함락과 디도의 사랑을 다섯 시간 가까이 그려요', reason_en = 'Considered the greatest French grand opera. Nearly five hours on the fall of Troy and Dido''s love' WHERE composer_id = 37 AND piece_id = 607 AND source = 'auto';
UPDATE composer_highlights SET reason = '독주 악기가 이야기 속 인물이 되는 교향곡이에요. 비올라가 주인공 해롤드를 맡아 이탈리아를 떠돌아요', reason_en = 'A symphony where a solo instrument becomes a character. The viola is Harold wandering through Italy' WHERE composer_id = 37 AND piece_id = 661 AND source = 'auto';
