UPDATE composer_highlights SET reason = '러시아 정교회 부활절 성가를 그대로 가져와 쓴 서곡이에요. 성가로 조용히 시작해 부활절 아침 종소리로 커져요', reason_en = 'Built on actual Orthodox Easter chants. It grows from quiet chant to Easter-morning bells' WHERE composer_id = 46 AND piece_id = 205 AND source = 'auto';
UPDATE composer_highlights SET reason = '러시아 역사 오페라의 출발점이 된 림스키의 첫 오페라예요. 이반 뇌제가 등장해요', reason_en = 'Rimsky''s first opera, a starting point for Russian historical opera. Ivan the Terrible appears' WHERE composer_id = 46 AND piece_id = 31392 AND source = 'auto';
UPDATE composer_highlights SET reason = '러시아 영웅 서사시 ''사드코''를 옮긴 오페라예요. ''인도 상인의 노래''가 따로 자주 불려요', reason_en = 'An opera from the Russian epic of Sadko. Its ''Song of the Indian Guest'' is often sung alone' WHERE composer_id = 46 AND piece_id = 31397 AND source = 'auto';
UPDATE composer_highlights SET reason = '차르 체제를 비꼬아 생전에 공연이 금지된 림스키의 마지막 오페라예요. ''태양 찬가''가 따로 널리 불려요', reason_en = 'Rimsky''s last opera, banned in his lifetime for mocking the tsar. Its ''Hymn to the Sun'' is widely sung' WHERE composer_id = 46 AND piece_id = 31406 AND source = 'auto';
UPDATE composer_highlights SET reason = '포레가 죽음을 ''행복한 해방''으로 보며 쓴 레퀴엠이에요. ''진노의 날''을 빼고 ''피에 예수''를 소프라노 독창으로 넣었어요', reason_en = 'Fauré said he saw death as a happy deliverance. No Dies irae; the ''Pie Jesu'' is a soprano solo' WHERE composer_id = 47 AND piece_id = 206 AND source = 'auto';
UPDATE composer_highlights SET reason = '후원자인 백작 부인에게 바치고 나중에 합창을 붙인 곡이에요. 현의 피치카토 위로 플루트가 느린 선율을 불러요', reason_en = 'Dedicated to a countess patron, with an optional chorus added later. The flute sings over plucked strings' WHERE composer_id = 47 AND piece_id = 207 AND source = 'auto';
UPDATE composer_highlights SET reason = '포레 소품 가운데 가장 널리 알려진 곡이에요. 흔들리는 반주 위로 플루트나 첼로가 선율을 불러요', reason_en = 'Fauré''s best-known short piece. Flute or cello sings over a gently rocking accompaniment' WHERE composer_id = 47 AND piece_id = 208 AND source = 'auto';
UPDATE composer_highlights SET reason = '이탈리아 시를 프랑스어로 옮겨 붙인 포레의 가곡이에요. 긴 선율 덕에 첼로 편곡으로도 자주 연주돼요', reason_en = 'Fauré''s song on an Italian poem in French. Its long melody is often played on cello' WHERE composer_id = 47 AND piece_id = 1211 AND source = 'auto';
UPDATE composer_highlights SET reason = '포레가 60대 후반에 완성한 오페라예요. 오디세우스를 기다리는 페넬로페를 절제된 음악으로 그려요', reason_en = 'The opera Fauré finished in his late sixties. Penelope waiting for Odysseus, in restrained music' WHERE composer_id = 47 AND piece_id = 2155 AND source = 'auto';
UPDATE composer_highlights SET reason = '열아홉 살 학생 때 작곡상을 받은 합창곡이에요. 흐르는 반주 위로 합창이 조용히 노래해요', reason_en = 'The choral piece that won Fauré a student composition prize at 19. The choir sings quietly over a flowing accompaniment' WHERE composer_id = 47 AND piece_id = 11526 AND source = 'auto';
UPDATE composer_highlights SET reason = '초연 땐 평이 갈렸지만 곧 푸치니 최고 흥행작이 됐어요. 1막에서 ''그대의 찬 손''과 ''내 이름은 미미''가 이어 나와요', reason_en = 'Mixed reviews at first, then Puccini''s biggest hit. Act 1 runs from ''Che gelida manina'' into ''Mi chiamano Mimì''' WHERE composer_id = 48 AND piece_id = 210 AND source = 'auto';
UPDATE composer_highlights SET reason = '테너 아리아의 대명사예요. 끝 ''빈체로''에서 테너가 높은 B음을 길게 끌어요', reason_en = 'THE tenor aria. The final ''Vincerò'' holds a high B' WHERE composer_id = 48 AND piece_id = 211 AND source = 'auto';
UPDATE composer_highlights SET reason = '푸치니 오페라 가운데 가장 극적인 작품으로 꼽혀요. 2막 ''노래에 살고 사랑에 살고'', 3막 ''별은 빛나건만''이 나와요', reason_en = 'Puccini''s most dramatic opera. Act 2 has ''Vissi d''arte'', Act 3 ''E lucevan le stelle''' WHERE composer_id = 48 AND piece_id = 212 AND source = 'auto';
UPDATE composer_highlights SET reason = '1904년 초연은 실패했지만 고쳐 다시 올려 성공한 오페라예요. 2막 ''어떤 개인 날''에서 초초상이 돌아올 배를 기다려요', reason_en = 'A fiasco in 1904, a success once revised. In ''Un bel dì'' Butterfly waits for the returning ship' WHERE composer_id = 48 AND piece_id = 213 AND source = 'auto';
UPDATE composer_highlights SET reason = '푸치니를 처음 스타로 만든 오페라예요. 3막 앞 간주곡이 따로 자주 연주돼요', reason_en = 'The opera that first made Puccini a star. The intermezzo before Act 3 is often played alone' WHERE composer_id = 48 AND piece_id = 31486 AND source = 'auto';
UPDATE composer_highlights SET reason = '푸치니가 음악학교 졸업 작품으로 쓴 미사예요. 뒤에 선율 일부를 <마농 레스코> 등 오페라에 옮겼어요', reason_en = 'Puccini''s graduation piece. He later reused parts in Manon Lescaut and other operas' WHERE composer_id = 48 AND piece_id = 31493 AND source = 'auto';
UPDATE composer_highlights SET reason = '지휘자 뷜로의 장례식에서 들은 찬가로 피날레를 떠올린 교향곡이에요. 5악장에서 합창이 아주 여리게 들어와요', reason_en = 'Mahler found his finale at the funeral of the conductor von Bülow. The chorus enters almost inaudibly' WHERE composer_id = 49 AND piece_id = 215 AND source = 'auto';
UPDATE composer_highlights SET reason = '4악장 ''아다지에토''는 아내 알마에게 보낸 사랑 고백으로 전해져요. 현악기와 하프만 연주해요', reason_en = 'The Adagietto is said to be a love letter to Alma. Strings and harp alone' WHERE composer_id = 49 AND piece_id = 216 AND source = 'auto';
UPDATE composer_highlights SET reason = '말러 입문으로 꼽히는 첫 교향곡이에요. 3악장에 돌림노래 ''프레르 자크''를 단조로 바꾼 장송 행진곡이 나와요', reason_en = 'The usual first Mahler. Its third movement turns ''Frère Jacques'' into a minor-key funeral march' WHERE composer_id = 49 AND piece_id = 217 AND source = 'auto';
UPDATE composer_highlights SET reason = '''천인 교향곡''이라 불릴 만큼 규모를 키운 교향곡이에요. 1부는 라틴어 찬가, 2부는 <파우스트> 마지막 장면이에요', reason_en = 'The ''Symphony of a Thousand'' pushed the symphony''s scale to its limit. Part 1 is a Latin hymn, Part 2 the end of Faust' WHERE composer_id = 49 AND piece_id = 218 AND source = 'auto';
UPDATE composer_highlights SET reason = '교향곡과 가곡을 하나로 합친 말러의 독특한 대작이에요. 마지막 ''고별'' 한 곡이 30분 가까이 이어지다 조용히 사라져요', reason_en = 'Mahler''s unique fusion of symphony and song cycle. The final ''Abschied'' alone runs nearly 30 minutes and fades away' WHERE composer_id = 49 AND piece_id = 219 AND source = 'auto';
UPDATE composer_highlights SET reason = '말러가 완성한 마지막 교향곡이자 후기 낭만주의의 끝자락으로 꼽혀요. 끝 악장 아다지오가 아주 여린 현악기 소리로 사라져요', reason_en = 'Mahler''s last completed symphony, seen as late Romanticism''s farewell. The final Adagio dissolves into the faintest strings' WHERE composer_id = 49 AND piece_id = 11293 AND source = 'auto';
UPDATE composer_highlights SET reason = '자연에서 사랑까지 단계를 밟는 말러의 가장 긴 교향곡이에요. 4악장에서 알토가 니체의 ''한밤의 노래''를 불러요', reason_en = 'Mahler''s longest symphony, climbing from nature to love. In the fourth movement an alto sings Nietzsche''s ''Midnight Song''' WHERE composer_id = 49 AND piece_id = 11933 AND source = 'auto';
UPDATE composer_highlights SET reason = '곡을 쓰고 몇 년 뒤 말러의 딸이 세상을 떠나 더 알려진 곡이에요. 두 아이를 잃은 뤼케르트의 시 다섯 편을 불러요', reason_en = 'Mahler lost his daughter a few years after writing it. Five poems Rückert wrote after losing two children' WHERE composer_id = 49 AND piece_id = 32380 AND source = 'auto';
UPDATE composer_highlights SET reason = '근대 음악의 출발점으로 자주 꼽히는 곡이에요. 플루트 독주가 반음계로 내려갔다 올라오는 선율로 시작해요', reason_en = 'Often named the starting point of modern music. A solo flute slides down and back up chromatically' WHERE composer_id = 50 AND piece_id = 221 AND source = 'auto';
UPDATE composer_highlights SET reason = '드뷔시 관현악의 정점으로 꼽혀요. 바다를 세 부분으로 그리고, 마지막 ''바람과 바다의 대화''에서 크게 몰아쳐요', reason_en = 'Seen as Debussy''s orchestral summit. The sea in three sketches, ending in the storm of ''Dialogue of the Wind and the Sea''' WHERE composer_id = 50 AND piece_id = 222 AND source = 'auto';
UPDATE composer_highlights SET reason = '세 살 딸에게 바친 피아노 모음곡이에요. 끝곡에서 바그너 <트리스탄> 첫머리를 놀리듯 인용해요', reason_en = 'Dedicated to his three-year-old daughter. The last piece pokes fun at the opening of Wagner''s Tristan' WHERE composer_id = 50 AND piece_id = 223 AND source = 'auto';
UPDATE composer_highlights SET reason = '드뷔시가 젊을 때 쓴 피아노 소품이에요. 낮은 펼친화음 위로 단순한 선율이 이어져요', reason_en = 'An early Debussy piano piece. A simple melody over low broken chords' WHERE composer_id = 50 AND piece_id = 456 AND source = 'auto';
UPDATE composer_highlights SET reason = '파리 카페 음악을 드뷔시식으로 비튼 왈츠예요. ''느린 왈츠보다 더 느리게''라는 제목대로 늘어지며 흔들려요', reason_en = 'Debussy''s twist on Parisian café music. True to its title, it lingers and sways' WHERE composer_id = 50 AND piece_id = 7443 AND source = 'auto';
UPDATE composer_highlights SET reason = '드뷔시 피아노곡 가운데 가장 화려한 곡으로 꼽혀요. 와토의 그림에서 나온 곡으로 끝에서 크게 터지며 끝나요', reason_en = 'Debussy''s most brilliant piano piece. Inspired by Watteau, it ends in a blaze' WHERE composer_id = 50 AND piece_id = 7542 AND source = 'auto';
UPDATE composer_highlights SET reason = '휘슬러의 그림 ''녹턴''에서 제목을 따온 곡이에요. 셋째 곡 ''세이렌''에서 여성 합창이 가사 없이 노래해요', reason_en = 'Its title comes from Whistler''s ''Nocturne'' paintings. In ''Sirènes'' a women''s choir sings without words' WHERE composer_id = 50 AND piece_id = 8526 AND source = 'auto';
UPDATE composer_highlights SET reason = '드뷔시 피아노곡 가운데 가장 널리 알려진 곡이에요. 여린 화음이 천천히 이어지다 가운데에서 펼친화음으로 흐르기 시작해요', reason_en = 'Debussy''s best-known piano piece. Soft chords move slowly, then begin to flow in arpeggios mid-way' WHERE composer_id = 50 AND piece_id = 8876 AND source = 'auto';
UPDATE composer_highlights SET reason = '20대 후반에 쓴 드뷔시 초기 피아노곡이에요. 셋잇단 펼친음이 처음부터 끝까지 이어지는 4분 남짓한 곡이에요', reason_en = 'An early Debussy piece from his late twenties. Four minutes of flowing triplet arpeggios' WHERE composer_id = 50 AND piece_id = 11034 AND source = 'auto';
UPDATE composer_highlights SET reason = '드뷔시가 완성한 단 하나의 오페라로 20세기 오페라의 출발점으로 꼽혀요. 노래가 대사처럼 흘러가요', reason_en = 'Debussy''s only completed opera, seen as where 20th-century opera begins. The singing flows like speech' WHERE composer_id = 50 AND piece_id = 32396 AND source = 'auto';
UPDATE composer_highlights SET reason = '낭만주의 피아노 협주곡의 대명사예요. 피아노 혼자 종소리 같은 화음을 여덟 번 점점 크게 치며 시작해요', reason_en = 'The Romantic piano concerto par excellence. It opens with eight bell-like piano chords, growing louder' WHERE composer_id = 51 AND piece_id = 225 AND source = 'auto';
UPDATE composer_highlights SET reason = '피아노 협주곡 가운데 가장 어려운 곡의 하나로 꼽혀요. 단순한 단선율로 조용히 시작해 점점 거대해져요', reason_en = 'Counted among the hardest piano concertos. It opens with a plain single line and grows enormous' WHERE composer_id = 51 AND piece_id = 226 AND source = 'auto';
UPDATE composer_highlights SET reason = '미국 망명 뒤 스위스 별장에서 쓴 곡이에요. 18변주는 파가니니 주제를 뒤집어 느리게 바꾼 선율이에요', reason_en = 'Written at his Swiss villa during his exile years. Variation 18 turns Paganini''s theme upside down' WHERE composer_id = 51 AND piece_id = 227 AND source = 'auto';
UPDATE composer_highlights SET reason = '열아홉 살 졸업 작품으로 차이콥스키의 칭찬을 받은 단막 오페라예요. 푸시킨의 시 <집시>가 원작이에요', reason_en = 'His teenage graduation opera, praised by Tchaikovsky. Based on Pushkin''s The Gypsies' WHERE composer_id = 51 AND piece_id = 681 AND source = 'auto';
UPDATE composer_highlights SET reason = '라흐마니노프 전주곡 가운데 자주 연주되는 곡이에요. 행진곡 리듬으로 시작해 가운데에서 느린 선율로 바뀌어요', reason_en = 'One of Rachmaninoff''s most played preludes. A march that turns into a slow melody mid-way' WHERE composer_id = 51 AND piece_id = 701 AND source = 'auto';
UPDATE composer_highlights SET reason = '라흐마니노프가 가장 아꼈다는 합창 교향곡이에요. 포의 시로 썰매·결혼·화재·장례의 종소리를 차례로 그려요', reason_en = 'The choral symphony he reportedly loved most. Poe''s sleigh, wedding, alarm and funeral bells' WHERE composer_id = 51 AND piece_id = 819 AND source = 'auto';
UPDATE composer_highlights SET reason = '라흐마니노프를 세계에 알린 첫 히트곡이에요. ''라–솔#–도#'' 세 음이 무겁게 울리며 시작해요', reason_en = 'The first hit that made Rachmaninoff famous. Three heavy notes, A–G♯–C♯, open it' WHERE composer_id = 51 AND piece_id = 1920 AND source = 'auto';
UPDATE composer_highlights SET reason = '가사 없이 모음 하나로 부르는 노래라 악기 편곡이 끝없이 나온 곡이에요. 열네 곡 가곡집의 마지막 곡이에요', reason_en = 'Sung on a single vowel, it has been arranged for countless instruments. The last of fourteen songs' WHERE composer_id = 51 AND piece_id = 2283 AND source = 'auto';
UPDATE composer_highlights SET reason = '첫 교향곡 실패를 딛고 성공한 라흐마니노프의 교향곡이에요. 3악장 클라리넷의 긴 독주 선율이 핵심이에요', reason_en = 'The symphony that redeemed the failure of his first. Its heart is the long clarinet solo in the slow movement' WHERE composer_id = 51 AND piece_id = 32413 AND source = 'auto';
UPDATE composer_highlights SET reason = '라흐마니노프의 마지막 작품이에요. 1악장 가운데 알토 색소폰 독주가 나오고, 끝에 ''진노의 날''이 다시 등장해요', reason_en = 'Rachmaninoff''s last work. An alto saxophone solo mid-first-movement; the ''Dies irae'' returns at the end' WHERE composer_id = 51 AND piece_id = 32418 AND source = 'auto';
UPDATE composer_highlights SET reason = '라벨 스스로 ''음악 없이 관현악만 있는 곡''이라 부른 실험이에요. 작은북이 같은 리듬을 15분 내내 치고 악기만 바뀌어요', reason_en = 'Ravel called it ''orchestral tissue without music''. One snare rhythm for 15 minutes while only the instruments change' WHERE composer_id = 52 AND piece_id = 230 AND source = 'auto';
UPDATE composer_highlights SET reason = '라벨이 젊을 때 쓰고 나중엔 ''형식이 빈약하다''며 낮춰 본 곡이에요. 관현악판에서는 호른이 느린 첫 선율을 불러요', reason_en = 'Ravel later dismissed this early piece as formally weak. In the orchestral version the horn sings the opening' WHERE composer_id = 52 AND piece_id = 231 AND source = 'auto';
UPDATE composer_highlights SET reason = '물을 그린 근대 피아노곡의 출발점으로 꼽혀요. 높은 음역의 빠른 펼친음이 반짝이며 이어져요', reason_en = 'Regarded as the first modern ''water'' piece for piano. Quick, glittering figures high on the keyboard' WHERE composer_id = 52 AND piece_id = 232 AND source = 'auto';
UPDATE composer_highlights SET reason = '미국 순회 때 들은 재즈를 받아들인 협주곡이에요. 채찍 소리로 시작하고, 2악장에서는 피아노 혼자 긴 선율을 불러요', reason_en = 'A concerto shaped by the jazz Ravel heard on his American tour. A whip crack opens it; the piano sings alone in the slow movement' WHERE composer_id = 52 AND piece_id = 233 AND source = 'auto';
UPDATE composer_highlights SET reason = '라벨 관현악의 정점으로 꼽혀요. ''새벽''에서 새소리와 물소리 위로 현악기가 해돋이를 그려요', reason_en = 'Seen as Ravel''s orchestral summit. In ''Daybreak'' strings paint a sunrise over birdsong and water' WHERE composer_id = 52 AND piece_id = 234 AND source = 'auto';
UPDATE composer_highlights SET reason = '집시 음악 연주를 밤새 듣고 쓴 곡이에요. 바이올린 혼자 4분 가까이 카덴차를 켠 뒤 반주가 들어와요', reason_en = 'Written after a Hungarian violinist played him Gypsy tunes all night. Nearly four minutes of solo cadenza open it' WHERE composer_id = 52 AND piece_id = 457 AND source = 'auto';
UPDATE composer_highlights SET reason = '콜레트가 대본을 쓴 라벨의 동화 오페라예요. 말썽 피운 아이 앞에 찻잔·의자·벽지 그림이 살아나 따져요', reason_en = 'Ravel''s fairy-tale opera with a libretto by Colette. Teacups, chairs and wallpaper come to life to scold a child' WHERE composer_id = 52 AND piece_id = 484 AND source = 'auto';
UPDATE composer_highlights SET reason = '라벨이 ''아파치'' 동료 예술가들에게 한 곡씩 바친 모음곡이에요. 넷째 ''어릿광대의 아침 노래''는 관현악판도 있어요', reason_en = 'Each piece is dedicated to a member of Ravel''s ''Apaches'' circle. The fourth also exists in an orchestral version' WHERE composer_id = 52 AND piece_id = 1900 AND source = 'auto';
UPDATE composer_highlights SET reason = '근대 피아노곡 가운데 가장 어려운 곡의 하나로 꼽혀요. 물의 요정·교수대·작은 악마 세 편의 시를 그려요', reason_en = 'Counted among the hardest modern piano works. Three poems: a water nymph, a gallows, a goblin' WHERE composer_id = 52 AND piece_id = 2849 AND source = 'auto';
UPDATE composer_highlights SET reason = '라벨 관현악 가운데 섬세한 곡으로 꼽혀요. 잠자는 숲속 미녀·엄지 동자·미녀와 야수 등 동화 다섯 장면을 그려요', reason_en = 'Ravel''s most delicate orchestral work. Five fairy-tale scenes, from Sleeping Beauty to Beauty and the Beast' WHERE composer_id = 52 AND piece_id = 26037 AND source = 'auto';
UPDATE composer_highlights SET reason = '20세기 음악의 출발점으로 꼽히는 발레예요. 바순이 아주 높은 음으로 열고, 엇갈린 강세의 리듬이 몰아쳐요', reason_en = 'Regarded as the start of 20th-century music. A high bassoon opens it, then irregular accents hammer on' WHERE composer_id = 81 AND piece_id = 309 AND source = 'auto';
UPDATE composer_highlights SET reason = '스트라빈스키를 하룻밤에 스타로 만든 발레예요. ''카스체이 왕의 지옥의 춤''에서 오케스트라 전체가 한꺼번에 내리쳐요', reason_en = 'The ballet that made Stravinsky a star overnight. The whole orchestra slams in for Kashchei''s ''Infernal Dance''' WHERE composer_id = 81 AND piece_id = 310 AND source = 'auto';
UPDATE composer_highlights SET reason = '<불새> 다음으로 발레 뤼스와 만든 발레예요. 두 조를 동시에 울리는 ''페트루슈카 화음''으로 장터 인형 이야기를 그려요', reason_en = 'His next ballet for the Ballets Russes after The Firebird. The two-key ''Petrushka chord'' tells a puppet tale' WHERE composer_id = 81 AND piece_id = 311 AND source = 'auto';
UPDATE composer_highlights SET reason = '보스턴 심포니 50주년을 위해 쓴 합창 교향곡이에요. 바이올린과 비올라를 빼고 썼어요', reason_en = 'A choral symphony for the Boston Symphony''s 50th anniversary. No violins or violas' WHERE composer_id = 81 AND piece_id = 312 AND source = 'auto';
UPDATE composer_highlights SET reason = '러시아 민담을 짧은 무대곡으로 옮긴 작품이에요. 여우와 수탉 이야기를 가수 넷과 작은 앙상블로 그려요', reason_en = 'A Russian folk tale as a short stage piece. Fox and rooster, told by four singers and a small band' WHERE composer_id = 81 AND piece_id = 31851 AND source = 'auto';
UPDATE composer_highlights SET reason = '구상부터 완성까지 10년 가까이 걸린 곡이에요. 피아노 네 대와 타악기가 러시아 시골 결혼식을 반주해요', reason_en = 'It took nearly ten years from idea to finished score. Four pianos and percussion accompany a village wedding' WHERE composer_id = 81 AND piece_id = 31859 AND source = 'auto';
UPDATE composer_highlights SET reason = '작은 편성 극음악의 본보기가 된 곡이에요. 악기 일곱과 낭독자가 병사가 악마에게 바이올린을 넘기는 이야기를 해요', reason_en = 'The model of small-scale music theatre. Seven players and a narrator tell of a soldier and the devil' WHERE composer_id = 81 AND piece_id = 31862 AND source = 'auto';
UPDATE composer_highlights SET reason = '콕토의 대본을 라틴어로 옮겨 부르는 오페라-오라토리오예요. 해설만 관객의 말로 하고 가수들은 거의 움직이지 않아요', reason_en = 'Cocteau''s libretto sung in Latin. Only the narration is in the audience''s language; the singers barely move' WHERE composer_id = 81 AND piece_id = 31884 AND source = 'auto';
UPDATE composer_highlights SET reason = '오든이 대본을 쓴 영어 오페라예요. 호가스의 판화 연작처럼 한 젊은이의 몰락을 장면마다 그려요', reason_en = 'An English opera with a libretto by Auden. Like Hogarth''s engravings, a young man''s fall scene by scene' WHERE composer_id = 81 AND piece_id = 31917 AND source = 'auto';
UPDATE composer_highlights SET reason = '스트라빈스키의 마지막 대작이에요. 15분이 안 되는 짧은 레퀴엠을 12음 기법으로 썼어요', reason_en = 'Stravinsky''s last major work. A requiem of under 15 minutes in twelve-tone style' WHERE composer_id = 81 AND piece_id = 31940 AND source = 'auto';
UPDATE composer_highlights SET reason = '스물다섯 쇤베르크의 곡으로, 초연 신청 때 화성이 낯설다고 거절당했어요. 달밤 두 연인의 고백을 현악기로 그려요', reason_en = 'Rejected by a Vienna society for its strange harmony. Strings paint two lovers'' confession on a moonlit walk' WHERE composer_id = 82 AND piece_id = 313 AND source = 'auto';
UPDATE composer_highlights SET reason = '20세기 성악의 이정표로 꼽혀요. 말하듯 노래하는 ''슈프레히슈티메''로 시 21편을 불러요', reason_en = 'A landmark of 20th-century vocal music. Twenty-one poems in half-spoken Sprechstimme' WHERE composer_id = 82 AND piece_id = 314 AND source = 'auto';
UPDATE composer_highlights SET reason = '생존자 증언을 바탕으로 2차 대전 직후 쓴 곡이에요. 낭독이 이어지다 끝에 남성 합창이 ''셰마 이스라엘''을 부르며 터져요', reason_en = 'Written just after the war from a survivor''s account. Narration ends with the men''s chorus bursting into the ''Shema''' WHERE composer_id = 82 AND piece_id = 315 AND source = 'auto';
UPDATE composer_highlights SET reason = '12음 기법이 처음 등장한 곡으로 음악사에 남았어요. 다섯 곡 가운데 마지막 ''왈츠''에서 그 기법을 써요', reason_en = 'Remembered as where twelve-tone writing first appears. The final Waltz uses it' WHERE composer_id = 82 AND piece_id = 316 AND source = 'auto';
UPDATE composer_highlights SET reason = '비판받은 작곡가가 살아남은 방식으로 이야기되는 교향곡이에요. 끝에서 팀파니가 같은 음을 계속 두드리며 승리를 외쳐요', reason_en = 'The symphony that tells how a condemned composer survived. The timpani pound one note in the ''triumphant'' ending' WHERE composer_id = 83 AND piece_id = 317 AND source = 'auto';
UPDATE composer_highlights SET reason = '전쟁 중 저항의 상징이 된 교향곡이에요. 1악장 작은북 리듬 위로 같은 선율이 되풀이되며 커지는 ''침략'' 대목이 있어요', reason_en = 'A wartime symbol of resistance. In the first movement one tune repeats and swells over a snare drum' WHERE composer_id = 83 AND piece_id = 318 AND source = 'auto';
UPDATE composer_highlights SET reason = '드레스덴 폭격 현장을 보고 사흘 만에 썼다는 4중주예요. 자기 이름 음형 D-S-C-H로 짜고 옛 작품을 여럿 인용해요', reason_en = 'Written in three days after seeing bombed-out Dresden. Built on D-S-C-H and quoting his earlier works' WHERE composer_id = 83 AND piece_id = 320 AND source = 'auto';
UPDATE composer_highlights SET reason = '로스트로포비치가 나흘 만에 외워 초연한 협주곡이에요. 네 음 동기를 첼로가 몰아치고 호른이 또 하나의 독주자로 나서요', reason_en = 'Rostropovich memorised it in four days for the premiere. The cello drives a four-note motif; the horn becomes a second soloist' WHERE composer_id = 83 AND piece_id = 321 AND source = 'auto';
UPDATE composer_highlights SET reason = '쇼스타코비치가 아들을 위해 쓴 밝은 협주곡이에요. 2악장에서 피아노가 느리고 단순한 선율을 길게 불러요', reason_en = 'The bright concerto he wrote for his son. In the slow movement the piano sings a long, simple melody' WHERE composer_id = 83 AND piece_id = 458 AND source = 'auto';
UPDATE composer_highlights SET reason = '20대 쇼스타코비치의 대담한 풍자 오페라예요. 고골 소설처럼 코가 달아나 혼자 돌아다녀요', reason_en = 'The young Shostakovich''s bold satirical opera. As in Gogol, a nose runs off on its own' WHERE composer_id = 83 AND piece_id = 12212 AND source = 'auto';
UPDATE composer_highlights SET reason = '바흐 <평균율>을 20세기에 다시 쓴 곡집이에요. 스물네 개 조마다 전주곡과 푸가를 짝지었어요', reason_en = 'A 20th-century Well-Tempered Clavier. A prelude and fugue in each of the 24 keys' WHERE composer_id = 83 AND piece_id = 12832 AND source = 'auto';
UPDATE composer_highlights SET reason = '쇼스타코비치 경음악 가운데 가장 유명한 곡이에요. 3박자 왈츠 선율을 색소폰과 현이 번갈아 불러요', reason_en = 'Shostakovich''s most famous light piece. Saxophone and strings trade the waltz tune' WHERE composer_id = 83 AND piece_id = 13454 AND source = 'auto';
UPDATE composer_highlights SET reason = '1941년 스탈린상을 받으며 큰 인기를 얻은 곡이에요. 바흐풍 전주곡과 푸가로 시작해 가벼운 끝 악장으로 끝나요', reason_en = 'A 1941 Stalin Prize winner and a big hit. It opens with a Bach-like prelude and fugue and ends lightly' WHERE composer_id = 83 AND piece_id = 13679 AND source = 'auto';
UPDATE composer_highlights SET reason = '소련 문화 관료를 비꼰 풍자곡으로 1989년에야 공개됐어요. 관료들의 연설을 노래로 흉내 내요', reason_en = 'A satire of Soviet cultural officials, made public only in 1989. It parodies their speeches in song' WHERE composer_id = 83 AND piece_id = 32731 AND source = 'auto';
UPDATE composer_highlights SET reason = '무용수들이 ''춤출 수 없다''고 반대해 초연이 늦어진 발레예요. ''기사들의 춤''에서 금관이 무겁게 밟아요', reason_en = 'Dancers called it undanceable and delayed its premiere. Heavy brass tread through the ''Dance of the Knights''' WHERE composer_id = 84 AND piece_id = 322 AND source = 'auto';
UPDATE composer_highlights SET reason = '하이든 양식을 20세기식으로 다시 쓴 신고전주의의 출발점이에요. 15분 남짓에 3악장을 미뉴에트 대신 가보트로 썼어요', reason_en = 'A starting point of neoclassicism, Haydn reimagined. About 15 minutes, with a gavotte in place of the minuet' WHERE composer_id = 84 AND piece_id = 323 AND source = 'auto';
UPDATE composer_highlights SET reason = '모스크바 어린이 극장의 의뢰로 며칠 만에 쓴 곡이에요. 피터는 현악기, 새는 플루트, 늑대는 호른이 맡아요', reason_en = 'Written in a matter of days for a Moscow children''s theatre. Peter is the strings, the bird a flute, the wolf the horns' WHERE composer_id = 84 AND piece_id = 324 AND source = 'auto';
UPDATE composer_highlights SET reason = '프로코피예프 협주곡 가운데 가장 자주 연주되는 곡이에요. 클라리넷 독주로 조용히 시작했다가 피아노가 뛰어들어요', reason_en = 'Prokofiev''s most performed concerto. A quiet clarinet solo, then the piano leaps in' WHERE composer_id = 84 AND piece_id = 325 AND source = 'auto';
UPDATE composer_highlights SET reason = '1943년 스탈린상을 받은 ''전쟁 소나타''예요. 끝 악장이 7/8박자로 같은 리듬을 몰아쳐요', reason_en = 'A ''War Sonata'' that won the 1943 Stalin Prize. The finale hammers one rhythm in 7/8' WHERE composer_id = 84 AND piece_id = 326 AND source = 'auto';
UPDATE composer_highlights SET reason = '디아길레프의 발레로 쓰기 시작했다가 퇴짜를 맞고 관현악곡이 됐어요. 고대 스키타이 의식을 거친 리듬으로 그려요', reason_en = 'Begun as a ballet for Diaghilev, rejected, and turned into an orchestral suite. Scythian rites in rough rhythms' WHERE composer_id = 84 AND piece_id = 11316 AND source = 'auto';
UPDATE composer_highlights SET reason = '프로코피예프의 첫 영화 음악에서 나온 모음곡이에요. ''트로이카''에서 썰매 방울 소리가 달려요', reason_en = 'From Prokofiev''s first film score. Sleigh bells race through the ''Troika''' WHERE composer_id = 84 AND piece_id = 11367 AND source = 'auto';
UPDATE composer_highlights SET reason = '프로코피예프 오페라 가운데 가장 많이 공연되는 작품이에요. 웃지 않는 왕자 이야기로 1분 남짓한 행진곡이 유명해요', reason_en = 'Prokofiev''s most performed opera. The tale of a prince who cannot laugh, with a famous one-minute March' WHERE composer_id = 84 AND piece_id = 11672 AND source = 'auto';
UPDATE composer_highlights SET reason = '에이젠시테인 영화 음악을 칸타타로 다시 쓴 곡이에요. ''얼음 위의 전투''에서 합창과 관현악이 크게 맞붙어요', reason_en = 'Eisenstein''s film score reworked as a cantata. Chorus and orchestra clash in the ''Battle on the Ice''' WHERE composer_id = 84 AND piece_id = 11869 AND source = 'auto';
UPDATE composer_highlights SET reason = '발몬트의 시 한 구절에서 제목을 따온 소품 스무 곡이에요. 1분 안팎의 곡이 저마다 다른 분위기를 잠깐씩 보여 줘요', reason_en = 'Twenty miniatures titled from a line by Balmont. Each piece of about a minute has its own mood' WHERE composer_id = 84 AND piece_id = 32747 AND source = 'auto';
UPDATE composer_highlights SET reason = '버르토크 관현악의 정점으로 꼽혀요. 악기마다 독주자처럼 나서고, 4악장에서 쇼스타코비치 7번 선율을 비꼬듯 인용해요', reason_en = 'Seen as Bartók''s orchestral summit. Every section gets a solo turn; the fourth movement mocks Shostakovich''s Seventh' WHERE composer_id = 85 AND piece_id = 327 AND source = 'auto';
UPDATE composer_highlights SET reason = '바젤 실내 관현악단의 의뢰로 쓴 곡이에요. 3악장이 실로폰의 한 음 연타로 시작해 영화 <샤이닝>에 쓰였어요', reason_en = 'Commissioned by a Basel chamber orchestra. The third movement opens with tapping xylophone and was used in The Shining' WHERE composer_id = 85 AND piece_id = 328 AND source = 'auto';
UPDATE composer_highlights SET reason = '버르토크 무대 음악 가운데 가장 격렬한 작품이에요. 줄거리 때문에 초연 뒤 공연이 금지됐어요', reason_en = 'Bartók''s most violent stage work. It was banned after its premiere for its plot' WHERE composer_id = 85 AND piece_id = 329 AND source = 'auto';
UPDATE composer_highlights SET reason = '20세기 피아노 교육의 기준이 된 곡집이에요. 아주 쉬운 곡부터 연주회용 곡까지 여섯 권 153곡이에요', reason_en = 'The 20th century''s standard piano method. 153 pieces in six books, from beginner to concert level' WHERE composer_id = 85 AND piece_id = 330 AND source = 'auto';
UPDATE composer_highlights SET reason = '베토벤 이후 가장 중요한 현악 4중주 연작으로 꼽혀요. 1908년부터 1939년까지 버르토크 양식의 변화가 다 담겨 있어요', reason_en = 'Considered the most important quartet cycle since Beethoven. Bartók''s whole evolution from 1908 to 1939' WHERE composer_id = 85 AND piece_id = 331 AND source = 'auto';
UPDATE composer_highlights SET reason = '버르토크의 단 하나의 오페라예요. 푸른 수염의 성에서 일곱 개의 문을 열 때마다 음악의 색이 바뀌어요', reason_en = 'Bartók''s only opera. Each of the seven doors in Bluebeard''s castle changes the music''s colour' WHERE composer_id = 85 AND piece_id = 31975 AND source = 'auto';
UPDATE composer_highlights SET reason = '버르토크 피아노 협주곡 가운데 가장 화려한 곡이에요. 1악장에는 현악기가 전혀 나오지 않아요', reason_en = 'The most dazzling of Bartók''s piano concertos. The first movement uses no strings at all' WHERE composer_id = 85 AND piece_id = 32014 AND source = 'auto';
UPDATE composer_highlights SET reason = '헝가리 바이올리니스트 세켈리의 의뢰로 쓴 협주곡이에요. 끝 악장이 1악장 주제를 변주해 다시 써요', reason_en = 'Commissioned by the Hungarian violinist Székely. The finale reworks the first movement''s themes' WHERE composer_id = 85 AND piece_id = 32027 AND source = 'auto';
UPDATE composer_highlights SET reason = '버르토크가 마지막으로 남긴 작품이에요. 아내 디타를 위해 쓴 밝은 협주곡으로, 끝 17마디는 제자가 완성했어요', reason_en = 'Bartók''s last work. A bright concerto for his wife Ditta; a pupil finished the final 17 bars' WHERE composer_id = 85 AND piece_id = 32033 AND source = 'auto';
UPDATE composer_highlights SET reason = '비올리스트 프림로즈의 의뢰를 받고 스케치만 남긴 채 세상을 떠난 곡이에요. 제자 셰를리가 완성했어요', reason_en = 'Commissioned by the violist Primrose and left in sketches at Bartók''s death. His pupil Serly completed it' WHERE composer_id = 85 AND piece_id = 32034 AND source = 'auto';
UPDATE composer_highlights SET reason = '클래식과 재즈를 처음 크게 합친 곡으로 꼽혀요. 클라리넷이 낮은 음에서 높은 음까지 미끄러져 오르며 시작해요', reason_en = 'Seen as the first big fusion of classical and jazz. The clarinet slides all the way up at the start' WHERE composer_id = 86 AND piece_id = 332 AND source = 'auto';
UPDATE composer_highlights SET reason = '거슈윈이 흑인 출연진만으로 올리라고 못 박은 오페라예요. 막이 오르자마자 자장가 ''Summertime''이 나와요', reason_en = 'Gershwin insisted it be performed by a Black cast. The lullaby ''Summertime'' comes right at the start' WHERE composer_id = 86 AND piece_id = 333 AND source = 'auto';
UPDATE composer_highlights SET reason = '파리 여행 중 사 온 택시 경적을 악보에 넣은 곡이에요. 파리 거리를 걷는 미국인의 하루를 그려요', reason_en = 'Gershwin brought taxi horns back from Paris and put them in the score. An American''s day on the streets of Paris' WHERE composer_id = 86 AND piece_id = 334 AND source = 'auto';
UPDATE composer_highlights SET reason = '<랩소디 인 블루> 성공 뒤 뉴욕 심포니의 의뢰로 쓴 협주곡이에요. 팀파니가 찰스턴 리듬으로 열어요', reason_en = 'Commissioned by the New York Symphony after Rhapsody in Blue. The timpani open in a Charleston rhythm' WHERE composer_id = 86 AND piece_id = 335 AND source = 'auto';
UPDATE composer_highlights SET reason = '뮤지컬에서 몇 번이나 빠졌다가 따로 히트한 노래예요. 반음으로 내려가는 선율이 재즈 가수들 사이에서 퍼졌어요', reason_en = 'Cut from more than one show before becoming a hit on its own. Its chromatic melody spread through jazz singers' WHERE composer_id = 86 AND piece_id = 1118 AND source = 'auto';
UPDATE composer_highlights SET reason = '거슈윈이 세상을 떠난 해에 나온 노래예요. 프레드 아스테어가 영화에서 불러 아카데미 주제가상 후보에 올랐어요', reason_en = 'From the year Gershwin died. Sung by Fred Astaire, it earned an Oscar nomination' WHERE composer_id = 86 AND piece_id = 33025 AND source = 'auto';
