UPDATE composer_highlights SET reason = '아이브스 실험의 집대성으로 꼽혀요. 지휘자가 여럿 필요할 만큼 복잡해 1965년에야 전곡이 초연됐어요', reason_en = 'Seen as the summation of Ives''s experiments. So complex it needs extra conductors; premiered complete in 1965' WHERE composer_id = 98 AND piece_id = 371 AND source = 'auto';
UPDATE composer_highlights SET reason = '아이브스가 직접 해설서를 붙여 자비로 출판한 소나타예요. 2악장에서 나무 막대로 건반 여러 개를 한꺼번에 눌러요', reason_en = 'Ives self-published it with his own book of essays. One passage uses a wooden board to press many keys at once' WHERE composer_id = 98 AND piece_id = 372 AND source = 'auto';
UPDATE composer_highlights SET reason = '보험 회사를 운영하며 틈틈이 쓴 아이브스의 관현악곡이에요. 둘째 곡 ''퍼트넘 캠프''에서 행진곡 둘이 다른 빠르기로 지나가요', reason_en = 'Written in spare hours while Ives ran an insurance firm. In ''Putnam''s Camp'' two marches pass at different speeds' WHERE composer_id = 98 AND piece_id = 373 AND source = 'auto';
UPDATE composer_highlights SET reason = '1974년 이탈리아에서 녹음해 누에보 탱고를 세계에 알린 곡이에요. 같은 리듬 위로 짧은 선율이 반복되며 몰아쳐요', reason_en = 'Recorded in Italy in 1974, it took nuevo tango worldwide. A short melody drives over one rhythm' WHERE composer_id = 99 AND piece_id = 374 AND source = 'auto';
UPDATE composer_highlights SET reason = '피아졸라 곡 가운데 가장 많이 편곡되는 곡의 하나예요. 느린 밀롱가 리듬 위로 긴 선율이 흘러요', reason_en = 'One of Piazzolla''s most arranged pieces. A long melody over a slow milonga rhythm' WHERE composer_id = 99 AND piece_id = 375 AND source = 'auto';
UPDATE composer_highlights SET reason = '피아졸라가 스스로 최고작으로 꼽은 곡이에요. 빠른 리듬 부분과 아버지를 추모하는 느린 선율이 번갈아 나와요', reason_en = 'The piece Piazzolla rated his best. Fast rhythmic sections alternate with a slow lament for his father' WHERE composer_id = 99 AND piece_id = 376 AND source = 'auto';
UPDATE composer_highlights SET reason = '비발디 <사계>와 짝지어 연주되는 탱고 사계예요. 따로따로 쓴 계절 탱고 네 곡을 묶었어요', reason_en = 'Tango''s Four Seasons, often paired with Vivaldi''s. Four seasonal tangos written separately' WHERE composer_id = 99 AND piece_id = 377 AND source = 'auto';
UPDATE composer_highlights SET reason = '피아졸라가 탱고로 쓴 오페라예요. 부에노스아이레스의 여인 마리아 이야기를 반도네온과 낭독으로 그려요', reason_en = 'Piazzolla''s tango opera. The story of María of Buenos Aires, with bandoneon and narration' WHERE composer_id = 99 AND piece_id = 606 AND source = 'auto';
UPDATE composer_highlights SET reason = '드뷔시가 관현악으로 옮겨 널리 알려진 곡이에요. 왼손이 두 화음을 번갈아 짚는 위로 느린 선율이 이어져요', reason_en = 'Made famous by Debussy''s orchestration. A slow melody over two alternating left-hand chords' WHERE composer_id = 100 AND piece_id = 378 AND source = 'auto';
UPDATE composer_highlights SET reason = '카바레 가수 폴레트 다르티를 위해 쓴 샹송이에요. 가벼운 왈츠 리듬 위로 사랑 노래가 이어져요', reason_en = 'Written for the cabaret singer Paulette Darty. A love song over a light waltz rhythm' WHERE composer_id = 100 AND piece_id = 380 AND source = 'auto';
UPDATE composer_highlights SET reason = '''배경음악''이라는 생각을 처음 내놓은 곡으로 꼽혀요. 짧은 음형이 끝없이 되풀이되도록 썼어요', reason_en = 'Regarded as the first ''background music''. Short figures meant to repeat endlessly' WHERE composer_id = 100 AND piece_id = 8179 AND source = 'auto';
UPDATE composer_highlights SET reason = '사티의 실험 정신을 보여 주는 피아노곡이에요. 마디줄 없이 쓰고 악보에 엉뚱한 연주 지시를 달았어요', reason_en = 'Satie''s experimental spirit in a piano piece. No bar lines and whimsical directions in the score' WHERE composer_id = 100 AND piece_id = 10942 AND source = 'auto';
UPDATE composer_highlights SET reason = '콕토가 기획하고 피카소가 무대를 맡은 발레 뤼스 공연이에요. 타자기·사이렌·권총 소리가 악기로 들어가요', reason_en = 'A Ballets Russes show devised by Cocteau and designed by Picasso. Typewriter, siren and pistol join the orchestra' WHERE composer_id = 100 AND piece_id = 32990 AND source = 'auto';
UPDATE composer_highlights SET reason = '마감에 쫓겨 하룻밤 사이에 썼다고 전하는 곡이에요. 실로폰과 작은북이 쉴 새 없이 두드리는 2분 남짓한 춤곡이에요', reason_en = 'Said to have been written overnight against a deadline. A two-minute dance driven by xylophone and snare drum' WHERE composer_id = 101 AND piece_id = 381 AND source = 'auto';
UPDATE composer_highlights SET reason = '레닌상을 받은 소련 발레예요. ''Adagio''가 BBC 드라마 <원딘 라인> 주제로 쓰였어요', reason_en = 'A Lenin Prize-winning Soviet ballet. Its Adagio became the theme of the BBC''s The Onedin Line' WHERE composer_id = 101 AND piece_id = 382 AND source = 'auto';
UPDATE composer_highlights SET reason = '오이스트라흐에게 바쳐 그가 초연하고 널리 알린 협주곡이에요. 아르메니아 민요풍 선율이 이어져요', reason_en = 'Dedicated to Oistrakh, who premiered it and made it famous. Full of Armenian folk-style melody' WHERE composer_id = 101 AND piece_id = 383 AND source = 'auto';
UPDATE composer_highlights SET reason = '레르몬토프 희곡 공연을 위해 쓴 음악을 모음곡으로 엮었어요. 첫 곡 ''왈츠''가 피겨 스케이팅 음악으로 자주 쓰여요', reason_en = 'Drawn from music for Lermontov''s play. Its Waltz is a figure skating favourite' WHERE composer_id = 101 AND piece_id = 384 AND source = 'auto';
UPDATE composer_highlights SET reason = '1962년 뒤셀도르프 플럭서스 공연에서 처음 선보인 작품이에요. 바이올린을 천천히 들어 올렸다가 탁자에 내리쳐 부숴요', reason_en = 'First shown at a 1962 Fluxus event in Düsseldorf. The violin is slowly raised, then smashed on a table' WHERE composer_id = 102 AND piece_id = 386 AND source = 'auto';
UPDATE composer_highlights SET reason = '숭실전문학교 2학년 때 쓴 김동진의 첫 히트곡이에요. 이은상의 시 ''내 고향 남쪽 바다''에 곡을 붙였어요', reason_en = 'Kim Dong-jin''s first hit, written as a second-year college student. A setting of Lee Eun-sang''s poem' WHERE composer_id = 103 AND piece_id = 388 AND source = 'auto';
UPDATE composer_highlights SET reason = '경희대 개교 25주년을 기념해 쓴 노래예요. 설립자 조영식의 시 ''오 내 사랑 목련화야''로 시작해요', reason_en = 'Written for Kyung Hee University''s 25th anniversary. It opens ''Oh, my beloved magnolia'', on the founder''s poem' WHERE composer_id = 103 AND piece_id = 389 AND source = 'auto';
UPDATE composer_highlights SET reason = '은사 김동명의 시를 외고 다니다 하루 만에 곡을 붙였다고 해요. ''내 마음은 호수요''로 시작하는 3박자 노래예요', reason_en = 'He is said to have set his old teacher Kim Dong-myeong''s poem in a single day. A triple-time song opening ''My heart is a lake''' WHERE composer_id = 103 AND piece_id = 390 AND source = 'auto';
UPDATE composer_highlights SET reason = '1968년에 쓴 김동진의 첫 교향곡이에요. 한국 민요풍 선율을 관현악으로 펼쳐요', reason_en = 'Kim Dong-jin''s first symphony, from 1968. Korean folk-style melodies in the orchestra' WHERE composer_id = 103 AND piece_id = 391 AND source = 'auto';
UPDATE composer_highlights SET reason = '민요 아리랑을 무대용 가곡으로 다시 쓴 곡이에요. 아리랑 선율에 피아노 반주를 입혔어요', reason_en = 'The folk song Arirang rewritten as a concert art song. The tune gets a piano accompaniment' WHERE composer_id = 103 AND piece_id = 460 AND source = 'auto';
UPDATE composer_highlights SET reason = '니체의 책 제목을 그대로 딴 교향시예요. 오르간의 낮은 음 위로 트럼펫이 ''도–솔–도''를 울리는 첫 2분이 핵심이에요', reason_en = 'A tone poem named after Nietzsche''s book. The heart is the opening: trumpets sound C–G–C over a low organ note' WHERE composer_id = 498 AND piece_id = 26025 AND source = 'auto';
UPDATE composer_highlights SET reason = '스톡홀름에서 초연된 리게티의 대규모 레퀴엠이에요. 스무 성부가 얽히는 키리에가 영화 <2001>에 쓰였어요', reason_en = 'Ligeti''s large requiem, premiered in Stockholm. Its twenty-voice Kyrie was used in 2001' WHERE composer_id = 499 AND piece_id = 26026 AND source = 'auto';
UPDATE composer_highlights SET reason = '큐브릭이 허락 없이 영화 <2001>에 써서 소송까지 간 곡이에요. 열여섯 성부가 같은 음들을 조금씩 어긋나게 불러요', reason_en = 'Kubrick used it in 2001 without permission, leading to a lawsuit. Sixteen voices sing the same notes slightly out of step' WHERE composer_id = 499 AND piece_id = 26027 AND source = 'auto';
UPDATE composer_highlights SET reason = '1961년 도나우에싱엔 초연으로 리게티의 이름을 알린 곡이에요. 선율 없이 소리의 색과 밀도만 천천히 바뀌어요', reason_en = 'Its 1961 Donaueschingen premiere made Ligeti''s name. No melody, just colour and density slowly shifting' WHERE composer_id = 499 AND piece_id = 26028 AND source = 'auto';
